const o=[{id:"overnight-holding",he:"אוברנייט",en:"Overnight Holding",category:"prop",definition:"השארת פוזיציה פתוחה אחרי סוף יום המסחר. ברוב חברות המימון בחוזים עתידיים חייבים לסגור הכול לפני שעה קבועה, ופוזיציה שנשארת פתוחה נסגרת אוטומטית או נחשבת הפרה.",related:["trading-session","account-breach"]},{id:"trading-automation",he:"אוטומציית מסחר",en:"Trading Automation",category:"platforms",definition:"שימוש בתוכנה לביצוע פעולות מסחר באופן אוטומטי, כגון פתיחת עסקאות, הצבת סטופים או ניהול פוזיציות. בחברות מימון יש לבדוק אילו סוגי אוטומציה מותרים."},{id:"optimization",he:"אופטימיזציה",en:"Optimization",category:"performance",definition:"תהליך שבו סוחר בוחן ומשנה פרמטרים באסטרטגיית המסחר כדי לשפר את ביצועיה. לדוגמה, שינוי שעות המסחר או תנאי הכניסה על בסיס תוצאות בקטסט."},{id:"order-block",he:"אורדר בלוק",en:"Order Block - OB",category:"ict",definition:"אזור מחיר המזוהה בשיטות ICT/SMC סביב נר או קבוצת נרות שקדמו לתנועה משמעותית. סוחרים עשויים לחפש תגובה כאשר המחיר חוזר לאזור, בהתאם למבנה השוק.",related:["breaker-block"]},{id:"order-flow",he:"אורדר פלואו",en:"Order Flow",category:"orderflow",definition:"ניתוח פעילות הקנייה והמכירה בשוק באמצעות נתוני עסקאות, נפחים ופקודות. מאפשר לסוחרים לבחון את התנהגות המשתתפים בשוק ברמות מחיר שונות.",links:[{type:"route",to:"/orderflow-course",label:"קורס Order Flow"},{type:"video",id:"imbalances"}]},{id:"demand-zone",he:"אזור ביקוש",en:"Demand Zone",category:"technical",definition:"אזור בגרף שממנו התפתחה בעבר תנועת מחיר משמעותית כלפי מעלה. סוחרים עשויים לחפש תגובת קנייה כאשר המחיר חוזר לאזור.",related:["supply-zone","supply-and-demand"]},{id:"discount-zone",he:"אזור דיסקאונט",en:"Discount Zone",category:"ict",definition:"בשיטת ICT/SMC, החלק התחתון של טווח מחירים מוגדר, מתחת לנקודת האמצע שלו. סוחרים עשויים להתייחס אליו כאזור לחיפוש הזדמנויות קנייה, בהתאם למבנה השוק.",related:["premium-zone"]},{id:"supply-zone",he:"אזור היצע",en:"Supply Zone",category:"technical",definition:"אזור בגרף שממנו התפתחה בעבר תנועת מחיר משמעותית כלפי מטה. סוחרים בוחנים אם המחיר ייתקל שוב בלחץ מכירה כאשר יחזור אליו.",related:["demand-zone","supply-and-demand"]},{id:"optimal-trade-entry",he:"אזור כניסה אופטימלי",en:"Optimal Trade Entry - OTE",category:"ict",definition:"מושג בשיטת ICT המתאר אזור כניסה אפשרי לעסקה, המבוסס על רמות תיקון פיבונאצ׳י בטווח מחירים מוגדר. סוחרים משתמשים באזור זה בשילוב עם מבנה השוק, כיוון המסחר ונזילות כדי לזהות הזדמנויות כניסה."},{id:"value-area",he:"אזור ערך",en:"Value Area - VA",category:"orderflow",definition:"טווח מחירים שבו התרכז שיעור מוגדר מנפח המסחר בפרק זמן מסוים, לרוב %70 בהגדרת Volume Profile נפוצה. משמש להבנת אזורי פעילות מרכזיים בשוק.",related:["value-area-high","value-area-low","point-of-control","volume-profile","previous-point-of-control"]},{id:"value-area-high",he:"אזור ערך עליון",en:"Value Area High - VAH",category:"orderflow",definition:"הגבול העליון של אזור הערך ב-Volume Profile. סוחרים בוחנים את התנהגות המחיר סביבו כדי לזהות דחייה, פריצה או קבלה של מחירים גבוהים יותר.",related:["value-area","value-area-low","point-of-control","volume-profile","previous-point-of-control"]},{id:"value-area-low",he:"אזור ערך תחתון",en:"Value Area Low - VAL",category:"orderflow",definition:"הגבול התחתון של אזור הערך ב-Volume Profile. משמש לזיהוי תגובות מחיר אפשריות ולבחינת מעבר בין מסחר בתוך אזור הערך למסחר מחוצה לו.",related:["value-area","value-area-high","point-of-control","volume-profile","previous-point-of-control"]},{id:"premium-zone",he:"אזור פרמיום",en:"Premium Zone",category:"ict",definition:"בשיטת ICT/SMC, החלק העליון של טווח מחירים מוגדר, מעל נקודת האמצע שלו. סוחרים עשויים לחפש באזור הזדמנויות מכירה בהתאם לכיוון ולמבנה השוק.",related:["discount-zone"]},{id:"win-rate",he:"אחוז הצלחה",en:"Win Rate",category:"performance",definition:"אחוז העסקאות שהסתיימו ברווח מתוך כלל העסקאות שנכללו בחישוב. לדוגמה, 6 עסקאות רווחיות מתוך 10 מייצגות %60 הצלחה. אחוז הצלחה גבוה אינו מבטיח רווחיות אם ההפסדים גדולים מהרווחים.",related:["risk-reward-ratio","profit-factor","trading-expectancy"],links:[{type:"article",slug:"journal-statistics-1-to-1"}]},{id:"risk-per-trade-percentage",he:"אחוז סיכון לעסקה",en:"Risk per Trade Percentage",category:"risk",definition:"אחוז ההון או מסגרת הסיכון שהסוחר מוכן להפסיד בעסקה אחת. משמש לקביעת גודל הפוזיציה בהתאם למרחק הסטופ ולשווי התנועה של החוזה.",links:[{type:"video",id:"risk-management"}]},{id:"atas",he:"אטאס",en:"ATAS",category:"platforms",definition:"פלטפורמה המתמקדת בניתוח זרימת פקודות ונפחי מסחר, באמצעות כלים כמו Footprint, Volume Profile וניתוח דלתא. היא מסייעת לבחון פעילות קונים ומוכרים ברמות מחיר שונות, בהתאם לנתוני השוק הזמינים."},{id:"imbalance",he:"אימבלנס",en:"Imbalance",category:"orderflow",definition:"חוסר איזון בפעילות המסחר. ב-Order Flow המונח מתייחס לפער בין נפחי קנייה ומכירה לפי שיטת מדידה מוגדרת, ואילו ב-ICT/SMC הוא משמש לעיתים לתיאור אזור של תנועת מחיר חדה ולא מאוזנת.",related:["footprint-chart","stacked-imbalance"],links:[{type:"video",id:"imbalances"}]},{id:"inversion-fair-value-gap",he:"אימבלנס הפוך",en:"Inversion Fair Value Gap - IFVG",category:"ict",definition:"מושג בשיטת ICT המתאר אזור Fair Value Gap שהמחיר פרץ דרכו, ולאחר מכן עשוי לשמש כאזור תגובה בכיוון ההפוך. סוחרים משתמשים בו לזיהוי שינוי אפשרי בהתנהגות המחיר ולחיפוש הזדמנויות כניסה בהתאם למבנה השוק.",related:["fair-value-gap"]},{id:"identity-verification",he:"אימות זהות",en:"Know Your Customer - KYC",category:"fundamentals",definition:"תהליך שבו חברה או ספק שירות פיננסי מאמתים את זהות הלקוח, בדרך כלל באמצעות מסמכי זיהוי ולעיתים גם אימות כתובת או פרטים נוספים. בחברות מימון התהליך עשוי להידרש לפני הפעלת חשבון ממומן, חתימה על הסכם או קבלת תשלום."},{id:"indicator",he:"אינדיקטור",en:"Indicator",category:"technical",definition:"כלי חישובי המציג מידע המבוסס על נתוני שוק, כגון מחיר, נפח או תנודתיות. דוגמאות נפוצות במסחר יומי הן ,RSI VWAP ו־ATR."},{id:"instant-funding",he:"אינסטנט פאנדינג/מימון מיידי",en:"Instant Funding",category:"prop",definition:"חשבון ממומן שמקבלים ישר, בלי לעבור מבחן. בדרך כלל הוא יקר יותר, והכללים בו קשוחים יותר, למשל דרודאון קטן יותר או חוק עקביות.",related:["funded-account","evaluation-account"]},{id:"inflation",he:"אינפלציה",en:"Inflation",category:"macro",definition:'עלייה כללית ומתמשכת ברמת המחירים במשק. נתוני אינפלציה בארה״ב, כגון CPI ו־PCE, עשויים להשפיע על התנודתיות בחוזים עתידיים על מדדי מניות, אג"ח ונכסים נוספים.',related:["consumer-price-index","personal-consumption-expenditures-price-index","core-inflation"]},{id:"core-inflation",he:"אינפלציית ליבה",en:"Core Inflation",category:"macro",definition:"מדד אינפלציה שאינו כולל רכיבים מסוימים הנחשבים תנודתיים, בדרך כלל מזון ואנרגיה במדדים אמריקאיים מרכזיים. משמש להערכת מגמות אינפלציה שעשויות להשפיע על ציפיות הריבית ועל השווקים.",related:["consumer-price-index","personal-consumption-expenditures-price-index","inflation"]},{id:"entry-confirmation",he:"אישור כניסה",en:"Entry Confirmation",category:"technical",definition:"תנאי שסוחר מחכה להתקיימותו לפני פתיחת עסקה, כגון שינוי מבנה שוק, תגובה באזור מחיר או הופעת נפח משמעותי. מסייע לפעול לפי תוכנית מסחר מוגדרת."},{id:"trading-strategy",he:"אסטרטגיית מסחר",en:"Trading Strategy",category:"performance",definition:"מערכת כללים שמגדירה באילו תנאים הסוחר נכנס לעסקה, כיצד הוא מנהל סיכונים ומתי הוא יוצא. מאפשרת לבדוק ביצועים ולשמור על עקביות בתהליך המסחר."},{id:"ask",he:"אסק",en:"Ask",category:"fundamentals",definition:"המחיר הנמוך ביותר שבו מוכר מוכן למכור כרגע חוזה בשוק. מוצג לצד מחיר ה־Bid ומשמש להבנת מרווח המחירים והנזילות הזמינה.",related:["bid","bid-ask-spread"],links:[{type:"video",id:"bid-ask"}]},{id:"relative-strength-index",he:"אר-אס-איי",en:"Relative Strength Index - RSI",category:"technical",definition:"אינדיקטור מומנטום המודד את עוצמת השינויים במחיר בסולם שבין 0 ל־100. משמש לזיהוי מצבים המכונים קניית יתר ומכירת יתר, לבחינת מומנטום ולזיהוי סטיות אפשריות בין המחיר לאינדיקטור."},{id:"r-trader-pro",he:"אר-טריידר פרו",en:"R|Trader Pro",category:"platforms",definition:"תוכנת מסחר וניהול חשבון של Rithmic, המאפשרת צפייה בנתוני שוק, הזנת פקודות ומעקב אחר פעילות החשבון. היא משמשת גם לחיבור ולניהול סביבת מסחר בחוזים עתידיים אצל ספקים תומכים."},{id:"balance-account-balance",he:"באלאנס",en:"Balance/Account Balance",category:"prop",definition:"יתרת החשבון לאחר שקלול רווחים והפסדים מעסקאות שנסגרו, בהתאם לאופן חישוב היתרה בפלטפורמה. בשונה מ-Equity, היתרה אינה משקפת בהכרח רווחים והפסדים מעסקאות שעדיין פתוחות.",related:["equity"]},{id:"buffer",he:"באפר/כרית ביטחון",en:"Buffer/Safety Buffer",category:"prop",definition:"סכום המשמש כמרווח ביטחון בין יתרת החשבון לבין רמת ההפסד המותרת. בחלק מחברות המימון נדרש לשמור על כרית ביטחון לפני משיכת רווחים, או להשאיר אותה בחשבון כדי להמשיך לסחור בתנאים מסוימים."},{id:"backtest-backtesting",he:"באקטסט",en:"Backtest/Backtesting",category:"performance",definition:"בדיקה של אסטרטגיית מסחר על נתוני עבר, במטרה לבחון כיצד הייתה מתפקדת בתנאי שוק היסטוריים. מאפשרת למדוד אחוזי הצלחה, יחס סיכון־סיכוי, רווחיות ונתונים נוספים לפני מסחר בכסף אמיתי או בחשבון מימון.",links:[{type:"video",id:"pine-script"}]},{id:"bollinger-bands",he:"בולינג׳ר/רצועות בולינג׳ר",en:"Bollinger Bands",category:"technical",definition:"אינדיקטור המורכב מממוצע נע ומשתי רצועות הממוקמות מעליו ומתחתיו בהתאם לסטיית התקן של המחיר. התרחבות הרצועות עשויה להעיד על עלייה בתנודתיות, והצטמצמותן על ירידה בתנודתיות, אך אינה מנבאת לבדה את כיוון התנועה הבאה."},{id:"bullish",he:"בוליש",en:"Bullish",category:"technical",definition:"מונח המתאר ציפייה לעליית מחיר או מצב שוק שורי. לדוגמה, מבנה שוק בוליש מתאפיין בדרך כלל בשיאים ושפלים עולים."},{id:"payout-bonus",he:"בונוס משיכה",en:"Payout Bonus",category:"prop",definition:"תשלום נוסף שסוחר עשוי לקבל מחברת מימון מעבר למשיכה הרגילה, בהתאם לתוכנית תגמולים או לתנאים מיוחדים. לא מדובר בהטבה שקיימת בכל חברת מימון, והתנאים משתנים בין החברות.",related:["payout","payout-cap","payout-waiting-period","profit-split"]},{id:"bookmap",he:"בוקמאפ",en:"Bookmap",category:"platforms",definition:"פלטפורמת מסחר וניתוח המציגה מידע על נזילות, עומק שוק ועסקאות שבוצעו באמצעות מפת חום וכלים נוספים. משמשת סוחרי Order Flow לזיהוי ריכוזי פקודות ושינויים בפעילות השוק.",links:[{type:"route",to:"/bookmap-guide",label:"מדריך Bookmap"}]},{id:"exchange",he:"בורסה",en:"Exchange",category:"fundamentals",definition:"זירת מסחר מוסדרת שבה מתבצעות עסקאות בחוזים עתידיים ובמכשירים פיננסיים נוספים. לדוגמה, חוזי E-mini ו-Micro E-mini על מדד Nasdaq-100 נסחרים ב-CME."},{id:"chicago-mercantile-exchange",he:"בורסת הסחורות של שיקגו",en:"Chicago Mercantile Exchange - CME",category:"fundamentals",definition:"בורסת נגזרים מרכזית בארצות הברית, שבה נסחרים בין היתר חוזים עתידיים על מדדי מניות, מטבעות וריביות. חוזי ES ו-NQ, וכן גרסאות המיקרו שלהם, נסחרים ב-CME."},{id:"bid",he:"ביד",en:"Bid",category:"fundamentals",definition:"המחיר הגבוה ביותר שקונה מוכן לשלם כרגע עבור חוזה בשוק. מוצג לצד מחיר ה-Ask ומשמש להבנת מרווח המחירים והנזילות הזמינה.",related:["ask","bid-ask-spread"],links:[{type:"video",id:"bid-ask"}]},{id:"bid-ask-spread",he:"ביד-אסק ספרד",en:"Bid-Ask Spread",category:"fundamentals",definition:"ההפרש בין מחיר הקנייה הגבוה ביותר (Bid) למחיר המכירה הנמוך ביותר (Ask). מרווח קטן מעיד בדרך כלל על נזילות טובה יותר ועשוי להפחית את עלויות הכניסה והיציאה מעסקאות.",related:["bid","ask"],links:[{type:"video",id:"bid-ask"}]},{id:"margin",he:"ביטחונות",en:"Margin",category:"fundamentals",definition:"סכום ביטחונות הנדרש לצורך פתיחה והחזקה של פוזיציה בחוזים עתידיים. דרישות הביטחונות משתנות בהתאם לחוזה, לברוקר ולשאלה אם הפוזיציה מוחזקת במהלך היום או מעבר לסיום המסחר."},{id:"bias-directional-bias",he:"בייאס",en:"Bias/Directional Bias",category:"ict",definition:"ההערכה של הסוחר לגבי הכיוון הצפוי של השוק, שורי או דובי, בהתאם לניתוח שביצע. לדוגמה, סוחר עם בייאס שורי יחפש בעיקר הזדמנויות קנייה, אך ההערכה אינה מבטיחה את כיוון המחיר."},{id:"partial",he:"ביצוע חלקי",en:"Partial",category:"fundamentals",definition:"מצב שבו רק חלק מכמות החוזים שהוזמנה בפקודת מסחר בוצע בפועל. לדוגמה, פקודת קנייה של חמישה חוזים עשויה להתמלא תחילה בשני חוזים בלבד."},{id:"broker",he:"ברוקר",en:"Broker",category:"fundamentals",definition:"חברה המספקת לסוחר גישה לביצוע עסקאות בשווקים הפיננסיים. במסחר בחוזים עתידיים הברוקר פועל באמצעות תשתיות מסחר וסליקה, ועשוי לקבוע דרישות ביטחונות ומגבלות סיכון."},{id:"break-even",he:"ברייק איבן",en:"Break Even - BE",category:"fundamentals",definition:"נקודת איזון שבה העסקה אינה מציגה רווח או הפסד ברוטו. סוחרים משתמשים במונח גם לתיאור הזזת הסטופ למחיר הכניסה, כדי לצמצם את הסיכון שנותר בעסקה. עמלות ועלויות ביצוע עדיין עשויות ליצור הפסד נטו.",related:["stop-loss","take-profit","bracket-order"]},{id:"breaker-block",he:"ברייקר בלוק",en:"Breaker Block",category:"ict",definition:"מושג בשיטת ICT המתאר אורדר בלוק שנכשל ונפרץ, ולאחר מכן עשוי לשמש כאזור תגובה בכיוון ההפוך. סוחרים עוקבים אחר חזרת המחיר לאזור כדי לבחון אפשרות להמשך תנועה.",related:["order-block"]},{id:"bearish",he:"בריש",en:"Bearish",category:"technical",definition:"מונח המתאר ציפייה לירידת מחיר או מצב שוק דובי. לדוגמה, מבנה שוק בריש מתאפיין בדרך כלל בשיאים ושפלים יורדים."},{id:"bracket-order",he:"ברקט אורדר",en:"Bracket Order",category:"fundamentals",definition:"מערך פקודות שבו פקודת הכניסה מלווה בדרך כלל בפקודת סטופ לוס ובפקודת טייק פרופיט. במערכות התומכות בכך, ביצוע אחת מפקודות היציאה מבטל את השנייה באמצעות מנגנון OCO.",related:["stop-loss","take-profit","break-even"],links:[{type:"video",id:"trading-orders"}]},{id:"gap",he:"גאפ",en:"Gap",category:"technical",definition:"פער בין מחיר הסגירה של תקופת מסחר אחת למחיר הפתיחה של התקופה הבאה, שבו לא התבצע מסחר בטווח המחירים שביניהם. גאפים עשויים להיווצר בעקבות חדשות, אירועים כלכליים או שינוי חד בציפיות המשתתפים בשוק."},{id:"fair-value-gap",he:"גאפ שווי הוגן",en:"Fair Value Gap - FVG",category:"ict",definition:"אזור חוסר איזון במחיר, המזוהה בשיטת ICT באמצעות מבנה של שלושה נרות, שבו קיים פער בין הטווח של הנר הראשון לטווח של הנר השלישי. סוחרים עשויים לחפש תגובה כאשר המחיר חוזר לאזור.",related:["inversion-fair-value-gap"]},{id:"position-size",he:"גודל פוזיציה",en:"Position Size",category:"risk",definition:"כמות החוזים שסוחר מחזיק בעסקה מסוימת. גודל הפוזיציה משפיע ישירות על הרווח או ההפסד מכל תנועת מחיר, ולכן נקבע בדרך כלל בהתאם למרחק הסטופ ולסיכון המתוכנן."},{id:"hedging",he:"גידור",en:"Hedging",category:"prop",definition:"פתיחת פוזיציה או שימוש במכשיר פיננסי שמטרתם לצמצם חשיפה לסיכון של פוזיציה אחרת. בחברות מימון מסוימות קיימות מגבלות על גידור, לרבות החזקת פוזיציות מנוגדות בחשבונות שונים.",links:[{type:"video",id:"hedging-explained"}]},{id:"contract-rollover",he:"גלגול חוזה",en:"Contract Rollover",category:"futures",definition:"מעבר ממסחר בחוזה עתידי שעומד להתקרב לפקיעה לחוזה בעל מועד פקיעה מאוחר יותר. סוחרים מבצעים את המעבר בדרך כלל כאשר נפח המסחר והנזילות עוברים לחוזה הבא.",related:["contract-expiration","continuous-futures-contract"],links:[{type:"video",id:"contract-rollover"}]},{id:"chart",he:"גרף",en:"Chart",category:"fundamentals",definition:"תצוגה חזותית של נתוני שוק לאורך זמן או לפי שיטת מדידה אחרת. סוחרים משתמשים בגרפים כדי לנתח תנועות מחיר, לזהות מבנים ולתכנן עסקאות."},{id:"candlestick-chart",he:"גרף נרות יפניים",en:"Candlestick Chart",category:"fundamentals",definition:"סוג גרף שבו כל נר מציג את מחירי הפתיחה, הסגירה, הגבוה והנמוך של תקופה מסוימת. מאפשר לזהות את התנהגות המחיר ואת מבנה השוק בצורה חזותית."},{id:"footprint-chart",he:"גרף פוטפרינט",en:"Footprint Chart",category:"orderflow",definition:"גרף המציג את נפח העסקאות שבוצעו ברמות מחיר שונות, לרוב תוך הפרדה בין עסקאות שבוצעו בצד ה-Bid ובצד ה-Ask. משמש לניתוח Order Flow ולזיהוי חוסר איזון, ספיגה ולחץ קנייה או מכירה.",related:["stacked-imbalance","imbalance"],links:[{type:"article",slug:"footprint-guide"},{type:"video",id:"footprint-guide"},{type:"route",to:"/orderflow-course",label:"קורס Order Flow"}]},{id:"dow-jones-industrial-average",he:"דאו ג'ונס",en:"Dow Jones Industrial Average - DJIA",category:"futures",definition:"מדד מניות אמריקאי הכולל 30 חברות גדולות ונבחרות, ומשוקלל לפי מחירי המניות שלהן. סוחרי חוזים עתידיים יכולים להיחשף לתנועת המדד באמצעות חוזי YM ו־MYM."},{id:"real-time-market-data",he:"דאטה בזמן אמת",en:"Real-Time Market Data",category:"fundamentals",definition:"נתוני שוק המתעדכנים בזמן אמת, לרבות מחירים, עסקאות ונפחי מסחר. במסחר בחוזים עתידיים נדרש לעיתים מנוי נתונים מתאים כדי לצפות במידע ללא השהיה."},{id:"non-farm-payrolls",he:"דוח התעסוקה",en:"Non-Farm Payrolls - NFP",category:"macro",definition:'נתון כלכלי אמריקאי המתפרסם בדרך כלל אחת לחודש ומציג את השינוי במספר המועסקים במגזרים שאינם חקלאיים, בכפוף להגדרות הדוח. הפרסום עשוי לגרום לתנודתיות משמעותית בחוזים עתידיים על מדדי מניות, אג"ח ומטבעות.',links:[{type:"video",id:"economic-news"}]},{id:"annual-tax-report",he:"דוח שנתי",en:"Annual Tax Return",category:"tax",definition:'הדוח שמגישים פעם בשנה לרשות המסים, עם כל ההכנסות וההוצאות של השנה הקודמת, כולל משיכות מחו"ל. כדאי לשמור לאורך השנה את כל הקבלות ואישורי המשיכה, כדי שלא תצטרך לחפש אותם בסוף.',related:["osek-patur","recognized-expenses","personal-exertion-income"]},{id:"depth-of-market",he:"דום",en:"Depth of Market - DOM",category:"fundamentals",definition:"חלון המציג את פקודות הקנייה והמכירה הממתינות ברמות מחיר שונות בספר הפקודות. מאפשר לעקוב אחר עומק השוק, להציב פקודות ולבחון שינויים בנזילות הגלויה."},{id:"market-dominance",he:"דומיננטיות בשוק",en:"Market Dominance",category:"orderflow",definition:"מונח כללי המתאר את הצד שנראה כבעל השפעה חזקה יותר על תנועת המחיר בתקופה מסוימת. ניתן להעריך זאת באמצעות מבנה המחיר, נפח המסחר ונתוני Order Flow."},{id:"selling-pressure",he:"דומיננטיות מוכרים",en:"Selling Pressure",category:"orderflow",definition:"מצב שבו פעילות המכירה מפעילה לחץ על המחיר כלפי מטה. סוחרים בוחנים את עוצמת המכירות ואת תגובת המחיר כדי להעריך אם הלחץ מוביל להמשך ירידה או נספג על ידי קונים."},{id:"buying-pressure",he:"דומיננטיות קונים",en:"Buying Pressure",category:"orderflow",definition:"מצב שבו פעילות הקנייה מפעילה לחץ על המחיר כלפי מעלה. בניתוח Order Flow ניתן לבחון אותו באמצעות עסקאות אגרסיביות, דלתא ונתוני נפח, אך לחץ קנייה אינו מבטיח עליית מחיר."},{id:"price-rejection",he:"דחיית מחיר",en:"Price Rejection",category:"technical",definition:"מצב שבו המחיר מגיע לרמה מסוימת אך אינו מצליח להתבסס מעבר לה, ולאחר מכן נע בכיוון ההפוך. סוחרים עשויים לזהות דחייה באמצעות פתילים בנרות, מבנה מחיר או נתוני Order Flow."},{id:"dxfeed",he:"די-אקס פיד",en:"dxFeed",category:"platforms",definition:"ספקית נתוני שוק המספקת מידע פיננסי בזמן אמת ומידע היסטורי למערכות מסחר וניתוח. במסגרת מסחר בחוזים עתידיים, נתוניה יכולים לשמש להצגת מחירים, עסקאות ועומק שוק, בהתאם לחבילת הנתונים ולהרשאות."},{id:"delayed-market-data",he:"דיליי בנתונים",en:"Delayed Market Data",category:"fundamentals",definition:"נתוני שוק המוצגים בהשהיה ביחס למסחר המתרחש בפועל. שימוש בנתונים מושהים עלול לפגוע בדיוק של ניתוח השוק ובקבלת החלטות במסחר יומי."},{id:"displacement",he:"דיספלייסמנט",en:"Displacement",category:"ict",definition:"מושג בשיטת ICT המתאר תנועת מחיר חזקה ומהירה יחסית, המתבטאת לעיתים בנרות בעלי גוף גדול ובתנועה כיוונית ברורה. דיספלייסמנט עשוי להופיע בעת שבירת מבנה שוק וליצור אזורי חוסר איזון כגון Fair Value Gap."},{id:"deepcharts",he:"דיפצ'ארטס",en:"DeepCharts",category:"platforms",definition:"פלטפורמה לניתוח ולמסחר בחוזים עתידיים, המתמקדת בכלים מתקדמים לניתוח נפח, עומק שוק וזרימת פקודות. היא כוללת אפשרויות כגון Footprint, ניתוח דלתא, פרופילי נפח וכלי ביצוע, בהתאם לגרסה ולחיבור הנתונים."},{id:"delta",he:"דלתא",en:"Delta",category:"orderflow",definition:"בניתוח Order Flow, ההפרש בין נפח העסקאות שבוצעו ביוזמת קונים לבין נפח העסקאות שבוצעו ביוזמת מוכרים. דלתא חיובית מצביעה על נפח קנייה אגרסיבית גבוה יותר, ודלתא שלילית על נפח מכירה אגרסיבית גבוה יותר.",related:["cumulative-volume-delta"]},{id:"cumulative-volume-delta",he:"דלתא מצטברת",en:"Cumulative Volume Delta - CVD",category:"orderflow",definition:"מדד המציג את הצטברות הדלתא לאורך תקופה מוגדרת. משמש לבחינת לחץ הקנייה והמכירה לאורך זמן ולזיהוי פערים אפשריים בין התנהגות המחיר לפעילות העסקאות.",related:["delta"]},{id:"demo-account-simulation-trading",he:"דמו",en:"Demo Account/Simulation Trading",category:"fundamentals",definition:"סביבת מסחר מדומה המאפשרת לתרגל פתיחת עסקאות, ניהול פוזיציות ושימוש בפלטפורמה ללא ביצוע עסקאות בחשבון מסחר חי. התוצאות בסימולציה אינן משקפות בהכרח את תנאי הביצוע במסחר אמיתי."},{id:"subscription-fee",he:"דמי מנוי",en:"Subscription Fee",category:"fundamentals",definition:"תשלום תקופתי הנגבה עבור שימוש בשירות או במסלול מסחר, בהתאם לתנאי החברה. בחברות מימון דמי המנוי עשויים לחול על שלב ההערכה, ולעיתים להיפסק לאחר מעבר השלב או סיום המנוי."},{id:"drawdown",he:"דרודאון",en:"Drawdown - DD",category:"prop",definition:"ירידה בערך החשבון ביחס לנקודת ייחוס, כגון שיא היסטורי של היתרה או ההון. בחברות מימון המונח משמש גם לתיאור מגבלות הפסד, שהאופן שבו הן מחושבות משתנה בין החברות והמסלולים.",related:["trailing-drawdown","maximum-drawdown-maximum-loss-limit"],links:[{type:"article",slug:"tradovate-drawdown"}]},{id:"trailing-drawdown",he:"דרודאון נגרר",en:"Trailing Drawdown",category:"prop",definition:"מגבלת הפסד שרמתה מתעדכנת כלפי מעלה בעקבות התקדמות החשבון, בהתאם לשיטת החישוב של חברת המימון. המגבלה עשויה להתבסס על יתרת החשבון או על שוויו בזמן אמת, ולעיתים מפסיקה לנוע לאחר הגעה לרמה מוגדרת.",related:["drawdown","intraday-trailing-drawdown","eod-trailing-drawdown","maximum-drawdown-maximum-loss-limit"],links:[{type:"video",id:"intraday-trailing"},{type:"video",id:"eod-trailing"},{type:"article",slug:"tradovate-drawdown"}]},{id:"static-drawdown",he:"דרודאון קבוע",en:"Static Drawdown",category:"prop",definition:"מגבלת הפסד שנקבעת ברמה קבועה ואינה עולה בעקבות רווחים בחשבון, בניגוד לדרודאון נגרר. אם יתרת החשבון או ההון העצמי מגיעים לרמת ההפסד שנקבעה, בהתאם לשיטת החישוב, הדבר עשוי להוביל להפרת כללי החשבון."},{id:"daily-loss-limit",he:"הגבלת הפסד יומית",en:"Daily Loss Limit - DLL",category:"prop",definition:"מגבלת הפסד המגדירה את ההפסד המרבי המותר במהלך יום מסחר, בהתאם לכללי חברת המימון או להגדרות מערכת ניהול הסיכונים. חריגה מהמגבלה עשויה לגרום לחסימת מסחר או להפרת כללי החשבון, בהתאם לתנאים.",related:["daily-stop","loss-limit"],links:[{type:"route",to:"/comparison",label:"השוואת חברות מימון"}]},{id:"scaling-in",he:"הגדלת פוזיציה",en:"Scaling In",category:"risk",definition:"הוספת חוזים לפוזיציה שכבר נפתחה, במטרה להגדיל את החשיפה לעסקה. הפעולה עשויה להגדיל את הרווח הפוטנציאלי, אך גם את הסיכון הכולל."},{id:"source-of-funds",he:"הוכחת מקור כספים",en:"Source of Funds - SOF",category:"fundamentals",definition:"מסמכים או מידע שנועדו להסביר מהיכן הגיעו כספים שהתקבלו או הועברו לחשבון. בנקים וספקי תשלום עשויים לבקש הוכחה כזו כחלק מבדיקות ציות ומניעת הלבנת הון, למשל באמצעות אישורי תשלום, הסכמים או דוחות מתאימים."},{id:"equity",he:"הון עצמי בחשבון",en:"Equity",category:"prop",definition:"השווי הנוכחי של החשבון, הכולל את יתרת החשבון ואת הרווחים או ההפסדים שטרם מומשו בעסקאות פתוחות. בניגוד ל-Balance, נתון זה משתנה גם בזמן שפוזיציות עדיין פעילות.",related:["balance-account-balance"]},{id:"recognized-expenses",he:"הוצאות מוכרות",en:"Deductible Business Expenses",category:"tax",definition:"הוצאות שאפשר להוריד מההכנסה לפני חישוב המס, כי הן שימשו להכנסה. אצל סוחר בחברת מימון אלה יכולות להיות חשבונות הערכה, דמי הפעלה, פלטפורמות ודאטה. תשמור קבלות על הכול.",related:["osek-patur","annual-tax-report","activation-fee"]},{id:"trend-reversal",he:"היפוך מגמה",en:"Trend Reversal",category:"technical",definition:"שינוי בכיוון המגמה הקיימת, ממגמת עלייה למגמת ירידה או להפך. סוחרים עשויים לזהות היפוך באמצעות שינוי במבנה השוק, שבירת רמות משמעותיות או סימנים נוספים המעידים על שינוי בכיוון המחיר."},{id:"supply-and-demand",he:"היצע וביקוש",en:"Supply and Demand",category:"technical",definition:"הכוחות של קונים ומוכרים המשפיעים על תנועת המחיר בשוק. בניתוח טכני משתמשים במושג גם לזיהוי אזורים שבהם התפתחה בעבר תנועת מחיר משמעותית בעקבות לחץ קנייה או מכירה.",related:["demand-zone","supply-zone"]},{id:"personal-exertion-income",he:"הכנסה מיגיעה אישית",en:"Personal Exertion Income",category:"tax",definition:"הכנסה מעבודה או מעסק שאתה עושה בעצמך, לעומת הכנסה פסיבית כמו ריבית או רווח הון. הסיווג משפיע על שיעור המס ועל נקודות הזיכוי, ואיך מסווגים משיכות מחברת מימון זו שאלה לרואה חשבון.",related:["annual-tax-report","osek-patur"]},{id:"wire-transfer",he:"העברה בנקאית",en:"Wire Transfer",category:"fundamentals",definition:"העברת כספים בין בנקים באמצעות מערכת להעברות בנקאיות, בתוך מדינה או בין מדינות. היא משמשת גם לקבלת תשלומים מחברות מימון, ועשויה להיות כרוכה בעמלות, בהמרת מטבע ובבדיקות מצד הבנקים המעורבים."},{id:"ach-transfer",he:"העברת ACH",en:"Automated Clearing House - ACH Transfer",category:"fundamentals",definition:"העברה בנקאית אלקטרונית המתבצעת באמצעות רשת ACH בארצות הברית. היא משמשת להעברת כספים בין חשבונות בנק תומכים, לרבות תשלומים לסוחרים, כאשר זמינותה תלויה בספק התשלום ובפרטי החשבון."},{id:"accumulation",he:"הצטברות",en:"Accumulation",category:"technical",definition:"מונח בניתוח טכני, המזוהה במיוחד עם שיטת ווייקוף (Wyckoff), המתאר שלב שבו עשויה להתבצע קנייה הדרגתית של נכס לאחר ירידה או בתקופת דשדוש. זיהוי השלב מבוסס על התנהגות המחיר ונפח המסחר, ואינו מאפשר לדעת בוודאות מי קונה."},{id:"scaling-out",he:"הקטנת פוזיציה",en:"Scaling Out",category:"risk",definition:"סגירת חלק מהחוזים בפוזיציה פתוחה תוך השארת יתרת הפוזיציה פעילה. מאפשרת לממש רווח או לצמצם חשיפה מבלי לסגור את העסקה כולה."},{id:"price-compression",he:"התכנסות מחירים",en:"Price Compression",category:"technical",definition:"מצב שבו תנועות המחיר נעשות צרות יותר והטווח שבו המחיר נסחר מצטמצם. סוחרים עשויים לעקוב אחר התכנסות לקראת פריצה אפשרית, אך כיוון הפריצה אינו ידוע מראש."},{id:"resistance",he:"התנגדות",en:"Resistance",category:"technical",definition:"אזור מחיר שבו הופיע בעבר היצע שהאט או עצר עלייה. משמש לזיהוי תגובות מחיר אפשריות, דחייה או פריצה של הרמה.",related:["support"]},{id:"market-profile-tpo-profile",he:"התפלגות נפח לפי זמן",en:"Market Profile/TPO Profile",category:"orderflow",definition:"שיטה להצגת פעילות השוק לפי משך הזמן שבו המחיר נסחר ברמות שונות, לרוב באמצעות יחידות TPO. מסייעת לניתוח מבנה יום המסחר, אזורי איזון והתרחבות טווח המחירים, ואינה זהה ל-Volume Profile."},{id:"wall-street",he:"וול סטריט",en:"Wall Street",category:"futures",definition:"כינוי מקובל לשוק ההון האמריקאי ולמרכזי הפעילות הפיננסית בארצות הברית. במסחר יומי בחוזים עתידיים משתמשים לעיתים במונח בהקשר של פתיחת המסחר במניות בארה״ב ושל פעילות סשן ניו יורק."},{id:"volume",he:"ווליום",en:"Volume",category:"orderflow",definition:"נפח המסחר הכולל שבוצע בחוזה עתידי במהלך תקופה מסוימת, הנמדד במספר החוזים שנסחרו. משמש לבחינת עוצמת הפעילות בשוק ולאישור או להטלת ספק בתנועות מחיר."},{id:"volume-weighted-average-price",he:"ווליום משוקלל למחיר",en:"VWAP – Volume Weighted Average Price",category:"orderflow",definition:"אינדיקטור המציג את המחיר הממוצע המשוקלל לפי נפח המסחר במהלך תקופה מוגדרת, לרוב יום המסחר. סוחרים משתמשים בו כנקודת ייחוס למחיר וכדי לבחון את מיקום המחיר ביחס לממוצע המשוקלל."},{id:"volume-profile",he:"ווליום פרופיל",en:"Volume Profile",category:"orderflow",definition:"כלי המציג את התפלגות נפח המסחר לפי רמות מחיר, במקום להציג את הנפח רק לאורך זמן. מאפשר לזהות רמות שבהן התרכז מסחר משמעותי, כולל נקודת השליטה (POC) ואזור הערך (Value Area).",related:["value-area","value-area-high","value-area-low","point-of-control","previous-point-of-control"]},{id:"workmarket",he:"וורק מרקט",en:"WorkMarket",category:"platforms",definition:"פלטפורמה לתשלום לעצמאים, שחלק מחברות המימון משלמות דרכה את המשיכות. נרשמים בה כנותן שירות, ממלאים פרטי מס ובנק ומקבלים דרכה את הכסף.",related:["payout","w-8ben"]},{id:"volatility-index",he:"ויקס",en:"Volatility Index - VIX",category:"macro",definition:"מדד התנודתיות של CBOE, המשקף את ציפיות השוק לתנודתיות במדד S&P 500 במהלך 30 הימים הקרובים, כפי שהן נגזרות ממחירי אופציות. סוחרי חוזים עתידיים עוקבים אחריו כאינדיקציה לרמת התנודתיות הצפויה בשוק המניות האמריקאי."},{id:"electronic-trading-platform",he:"זירת מסחר אלקטרונית",en:"Electronic Trading Platform",category:"fundamentals",definition:"מערכת המאפשרת לסוחרים לצפות בנתוני שוק, להזין פקודות ולנהל עסקאות באופן אלקטרוני. במסחר בחוזים עתידיים משתמשים בפלטפורמות כגון Tradovate, NinjaTrader ו-Quantower."},{id:"time-in-force",he:"זמן פקודה",en:"TIF – Time in Force",category:"fundamentals",definition:"הגדרה הקובעת למשך כמה זמן פקודת מסחר תישאר פעילה או באילו תנאים תבוטל. דוגמאות נפוצות הן DAY, פקודה התקפה ליום המסחר, ו-GTC, פקודה שנשארת פעילה עד לביטולה או עד לפקיעתה בהתאם לכללי המערכת."},{id:"e-mini-futures-contract",he:"חוזה מיני",en:"E-mini Futures Contract",category:"futures",definition:"חוזה עתידי מוקטן ביחס לחוזה סטנדרטי גדול יותר, בהתאם להגדרות הבורסה. חוזי E-mini כגון ES ו־NQ נפוצים במסחר יומי על מדדי המניות האמריקאיים.",related:["micro-futures-contract","futures-contract"]},{id:"micro-futures-contract",he:"חוזה מיקרו",en:"Micro Futures Contract",category:"futures",definition:"חוזה עתידי בעל מכפיל קטן יותר מהחוזה המקביל בגודל הרגיל. לדוגמה, חוזה MNQ מעניק חשיפה של עשירית מחוזה NQ, ומאפשר לסוחרים לנהל פוזיציות קטנות יותר.",related:["e-mini-futures-contract","futures-contract"]},{id:"futures-contract",he:"חוזה עתידי",en:"Futures Contract",category:"futures",definition:"הסכם סטנדרטי הנסחר בבורסה, המחייב קנייה או מכירה של נכס בסיס במועד עתידי לפי תנאי החוזה. במסחר יומי סוחרים רבים פותחים וסוגרים פוזיציות בחוזים עתידיים כדי להרוויח מתנודות המחיר, ללא כוונה להגיע לפקיעה.",related:["micro-futures-contract","e-mini-futures-contract"]},{id:"continuous-futures-contract",he:"חוזה רציף",en:"Continuous Futures Contract",category:"futures",definition:"סדרת נתוני מחיר המחברת חוזים עתידיים ממועדי פקיעה שונים לגרף היסטורי אחד. מאפשרת לבצע ניתוח טכני ובקטסט לאורך תקופות ארוכות, אך המחירים ההיסטוריים עשויים להיות מותאמים בהתאם לשיטת החיבור.",related:["contract-rollover","contract-expiration"]},{id:"inactivity-rule",he:"חוסר פעילות",en:"Inactivity Rule",category:"prop",definition:"כלל הקובע מה נחשב לחשבון שאינו פעיל במשך תקופה מסוימת. בהתאם לתנאי חברת המימון, חוסר פעילות ממושך עשוי להוביל להגבלת החשבון, לסגירתו או לאובדן זכאות להמשך שימוש בו."},{id:"consistency-rule",he:"חוק עקביות",en:"Consistency Rule",category:"prop",definition:"כלל שנועד להגביל את ריכוז הרווחים ביום מסחר בודד או בעסקה מסוימת ביחס לרווח הכולל. אופן החישוב, השלב שבו הכלל חל והשלכות החריגה משתנים בין חברות המימון והמסלולים."},{id:"account-renewal",he:"חידוש חשבון",en:"Account Renewal / Monthly Subscription",category:"prop",definition:"חיוב חודשי על חשבון הערכה שנמכר כמנוי. אם לא עברת את המבחן עד תאריך החידוש, תחויב שוב. יש חברות שמוכרות חשבון בתשלום חד פעמי, בלי חידוש.",related:["evaluation-account","account-reset","activation-fee"]},{id:"evaluation-account",he:"חשבון הערכה",en:"Evaluation Account",category:"prop",definition:"חשבון המשמש לבחינת ביצועי הסוחר במסגרת תהליך הקבלה לחברת מימון. הסוחר נדרש לעמוד ביעדים ובכללי המסחר שנקבעו לפני שיוכל להתקדם לשלב הבא.",related:["funded-account","live-account"],links:[{type:"route",to:"/comparison",label:"השוואת חברות מימון"}]},{id:"live-account",he:"חשבון לייב",en:"Live Account",category:"prop",definition:"חשבון שבו פקודות המסחר מבוצעות בשוק האמיתי, בניגוד לחשבון סימולציה. בחברות מימון מעבר לחשבון Live עשוי להיות כפוף לקריטריונים נוספים ולכללי ניהול סיכונים שונים.",related:["evaluation-account","funded-account"]},{id:"funded-account",he:"חשבון ממומן",en:"Funded Account",category:"prop",definition:"חשבון המוענק לסוחר לאחר שעמד בתנאי חברת המימון, בהתאם למודל הפעילות שלה. בחלק מהחברות מדובר בחשבון סימולציה המזכה בתגמולים על ביצועים, ובאחרות קיימת אפשרות למעבר למסחר בחשבון חי.",related:["evaluation-account","live-account"],links:[{type:"route",to:"/comparison",label:"השוואת חברות מימון"}]},{id:"market-exposure",he:"חשיפה לשוק",en:"Market Exposure",category:"risk",definition:"היקף הסיכון או ההשתתפות של הסוחר בתנועות המחיר של השוק באמצעות פוזיציות פתוחות. החשיפה מושפעת מכמות החוזים, ממכפיל החוזה וממאפייני הנכס הנסחר."},{id:"daily-range",he:"טווח יומי",en:"Daily Range",category:"technical",definition:"המרחק בין המחיר הגבוה ביותר למחיר הנמוך ביותר שנרשמו במהלך יום מסחר. משמש להערכת היקף התנועה היומית ולהשוואת התנודתיות בין ימי מסחר שונים."},{id:"trading-range",he:"טווח מסחר",en:"Trading Range",category:"technical",definition:"טווח מחירים שבו השוק נע בין גבול עליון לתחתון, ללא מגמה ברורה לאורך התקופה הנבחנת. סוחרים עשויים לחפש עסקאות בתוך הטווח או להמתין לפריצה של אחד מגבולותיו."},{id:"opening-range",he:"טווח פתיחה",en:"Opening Range - OR",category:"technical",definition:"טווח המחירים שנוצר במהלך פרק זמן מוגדר מתחילת סשן המסחר, למשל הדקות הראשונות לאחר פתיחת שוק המניות האמריקאי. סוחרים משתמשים בגבולות הטווח לזיהוי פריצות ותגובות מחיר אפשריות."},{id:"w-8ben",he:"טופס W-8BEN",en:"Form W-8BEN",category:"tax",definition:"טופס של רשות המסים האמריקאית שבו מצהירים שאתה לא תושב ארצות הברית. רוב חברות המימון ופלטפורמות התשלום מבקשות אותו לפני המשיכה הראשונה. הוא לא פוטר אותך מדיווח בישראל.",related:["payout","annual-tax-report","rise"]},{id:"topstepx",he:"טופסטפ אקס",en:"TopstepX",category:"platforms",definition:"פלטפורמת מסחר המיועדת לסוחרי חברת המימון Topstep ומאפשרת מסחר בחוזים עתידיים, צפייה בגרפים וניהול עסקאות. היא כוללת גם כלים לניהול סיכונים, כאשר זמינותם ותנאי השימוש בהם נקבעים על ידי Topstep."},{id:"timeframe",he:"טיים פריים",en:"Timeframe",category:"fundamentals",definition:"מסגרת הזמן שעל פיה מוצגים נתוני המחיר בגרף. לדוגמה, בגרף של חמש דקות כל נר מייצג את פעילות המחיר במהלך חמש דקות, וסוחרים משלבים לעיתים כמה מסגרות זמן בניתוח שלהם."},{id:"take-profit",he:"טייק פרופיט",en:"Take Profit - TP",category:"fundamentals",definition:"פקודת יציאה או יעד מחיר שנועדו לממש רווח כאשר השוק מגיע לרמה שהוגדרה מראש. ניתן להציב טייק פרופיט כחלק ממערך פקודות לניהול העסקה, בהתאם לפלטפורמת המסחר.",related:["stop-loss","bracket-order","break-even"]},{id:"tick",he:"טיק",en:"Tick",category:"fundamentals",definition:"יחידת שינוי המחיר המינימלית המותרת בחוזה עתידי מסוים. לדוגמה, בחוזי NQ ו־MNQ טיק אחד שווה לתנועה של 0.25 נקודות מדד, אך הערך הכספי שלו שונה בין החוזים."},{id:"tradovate",he:"טריידובייט",en:"Tradovate",category:"platforms",definition:"פלטפורמת מסחר בחוזים עתידיים המאפשרת צפייה בגרפים, הזנת פקודות וניהול פוזיציות. היא פועלת בסביבה מבוססת ענן ומשמשת גם סוחרים העובדים דרך חברות מימון התומכות בה."},{id:"tradezella",he:"טריידזלה",en:"TradeZella",category:"platforms",definition:"יומן מסחר דיגיטלי המאפשר לתעד עסקאות, לנתח ביצועים ולבחון דפוסים חוזרים בהתנהלות הסוחר. הוא משמש בין היתר למעקב אחר אסטרטגיות, טעויות, נתונים סטטיסטיים והתקדמות לאורך זמן."},{id:"tradingview",he:"טריידינג ויו",en:"TradingView",category:"platforms",definition:"פלטפורמה לניתוח גרפים פיננסיים הכוללת אינדיקטורים, כלי שרטוט, התראות ושיתוף רעיונות מסחר. ניתן לבצע באמצעותה מסחר דרך ברוקרים וחיבורים נתמכים, אך האפשרות תלויה בנכס ובספק השירות."},{id:"tradesyncer",he:"טריידסינקר",en:"TradeSyncer",category:"platforms",definition:"כלי המיועד לסנכרון ולהעתקת עסקאות בין חשבונות מסחר נתמכים. הוא מאפשר לבצע פעולות מחשבון מוביל ולשכפל אותן בחשבונות אחרים, בהתאם להגדרות, לחיבורים ולמגבלות השירות."},{id:"trading-day",he:"יום מסחר",en:"Trading Day",category:"prop",definition:"יום שבו מתקיימת פעילות מסחר בבורסה בהתאם ללוח הזמנים שלה. בחוזים עתידיים, יום המסחר עשוי להתחיל בערב של היום הקלנדרי הקודם, ולכן אינו בהכרח חופף לחצות או לשעות המסחר הרגילות במניות."},{id:"profitable-trading-day",he:"יום מסחר רווחי",en:"Profitable Trading Day",category:"prop",definition:"יום מסחר שבו הסוחר עומד בהגדרת הרווח היומי שנקבעה. בחברות מימון מסוימות נדרש לצבור ימי מסחר רווחיים כתנאי למעבר שלב או למשיכת רווחים, ולעיתים נקבע רף רווח מינימלי כדי שיום ייחשב כרווחי."},{id:"trading-journal",he:"יומן מסחר",en:"Trading Journal",category:"performance",definition:"יומן מסחר שבו מתעדים עסקאות, תוצאות, סיבות לכניסה וליציאה וטעויות שבוצעו. משמש לניתוח ביצועים ולזיהוי דפוסים חוזרים בהתנהלות הסוחר.",links:[{type:"article",slug:"trading-journal-guide"},{type:"video",id:"journal-tutorial"},{type:"route",to:"https://journal.antartrade.co.il",label:"יומן המסחר החינמי"}]},{id:"risk-reward-ratio",he:"יחס סיכון-סיכוי",en:"Risk-Reward Ratio - R:R",category:"risk",definition:"היחס בין ההפסד המתוכנן בעסקה לבין הרווח הפוטנציאלי שלה. לדוגמה, בעסקה שבה הסיכון הוא 200 דולר והיעד הוא 400 דולר, יחס הסיכון-סיכוי הוא 1:2. משמש לתכנון עסקאות ולהערכת כדאיותן לצד אחוז ההצלחה.",related:["win-rate","profit-factor","trading-expectancy"],links:[{type:"video",id:"ratio-trap"}]},{id:"profit-factor",he:"יחס רווחיות",en:"Profit Factor - PF",category:"performance",definition:"מדד המחושב באמצעות חלוקת סך הרווחים הגולמיים בסך ההפסדים הגולמיים בערך מוחלט. ערך הגבוה מ-1 מצביע על כך שסך הרווחים גבוה מסך ההפסדים בתקופה שנבדקה, לפני עלויות מסחר אם אלה לא נכללו בנתונים.",related:["win-rate","risk-reward-ratio","trading-expectancy"],links:[{type:"article",slug:"journal-statistics-1-to-1"}]},{id:"minimum-trading-days",he:"ימי מסחר מינימליים",en:"Minimum Trading Days",category:"prop",definition:"מספר ימי המסחר שסוחר נדרש להשלים כדי לעמוד בתנאי מסלול מסוים בחברת מימון. הדרישה עשויה לחול בשלב ההערכה, לפני משיכה או בשלבים אחרים, בהתאם לכללי החברה."},{id:"profit-target",he:"יעד רווח",en:"Profit Target",category:"prop",definition:"רמת רווח מוגדרת שסוחר או חברת מימון מציבים כמטרה. במסחר עצמאי מדובר לרוב ביעד לעסקה או לתקופה, ואילו בחברות מימון יעד הרווח עשוי להיות תנאי למעבר שלב ההערכה."},{id:"power-of-three",he:"כוח השלוש",en:"Power of Three - PO3 / AMD",category:"ict",definition:"מודל בשיטת ICT המתאר שלושה שלבים אפשריים בהתנהגות המחיר: צבירה (Accumulation), מניפולציה (Manipulation) והפצה (Distribution). סוחרים משתמשים במודל כדי לנתח תנועות סביב טווחי מחירים ונזילות במהלך יום המסחר."},{id:"buying-power",he:"כוח קנייה",en:"Buying Power",category:"fundamentals",definition:"היקף החשיפה הכספית שסוחר יכול לפתוח באמצעות ההון והביטחונות הזמינים בחשבונו. במסחר בחוזים עתידיים כוח הקנייה מושפע מדרישות המרווח, מגבלות הברוקר או חברת המימון ומספר החוזים המותר."},{id:"market-direction",he:"כיוון השוק",en:"Market Direction",category:"technical",definition:"הכיוון שבו המחיר נע במהלך תקופה מסוימת - כלפי מעלה, כלפי מטה או ללא כיוון ברור. סוחרים בוחנים את כיוון השוק באמצעות מבנה המחיר, שיאים ושפלים ונתונים נוספים כדי לתכנן את העסקאות שלהם."},{id:"aggressive-entry",he:"כניסה אגרסיבית",en:"Aggressive Entry",category:"technical",definition:"פתיחת עסקה בשלב מוקדם יחסית, לפני שמתקבלים כל אישורי הכניסה האפשריים של האסטרטגיה. כניסה כזו עשויה לאפשר מחיר כניסה נוח יותר, אך כרוכה בסיכון גבוה יותר לאיתות שגוי."},{id:"economic-calendar",he:"לוח שנה כלכלי",en:"Economic Calendar",category:"macro",definition:"לוח המציג מועדי פרסום של נתונים ואירועים כלכליים, כגון CPI, NFP והחלטות ריבית. סוחרי חוזים עתידיים נעזרים בו כדי להיערך לתנודתיות אפשרית ולבדוק מגבלות מסחר בזמן חדשות בחברות מימון.",links:[{type:"route",to:"/economic-calendar",label:"לוח שנה כלכלי"},{type:"video",id:"economic-news"}]},{id:"lot",he:"לוט",en:"Lot",category:"fundamentals",definition:'יחידת כמות מסחר המקובלת בשווקים מסוימים, בעיקר במט"ח. במסחר בחוזים עתידיים הכמות נמדדת בדרך כלל במספר חוזים, ולכן המונח פחות מרכזי בתחום זה.'},{id:"long-position",he:"לונג",en:"Long Position",category:"fundamentals",definition:"פוזיציית קנייה שנפתחת מתוך ציפייה שמחיר החוזה העתידי יעלה. הסוחר מרוויח כאשר המחיר עולה ביחס למחיר הכניסה, ומפסיד כאשר הוא יורד.",related:["short-selling-short-position"]},{id:"loss-limit",he:"לוס לימיט",en:"Loss Limit",category:"risk",definition:"מגבלת הפסד המגדירה את רמת ההפסד המרבית המותרת בחשבון או בתקופת מסחר מסוימת. בחברות מימון קיימים סוגים שונים של מגבלות הפסד, והפרתן עשויה להוביל לחסימת מסחר או לפסילת החשבון.",related:["daily-loss-limit","daily-stop"]},{id:"liquidity-pool",he:"ליקווידיטי פול",en:"Liquidity Pool",category:"ict",definition:"אזור שבו צפוי להימצא ריכוז של פקודות, כגון סטופים מעל שיאים או מתחת לשפלים. בשיטות ICT/SMC סוחרים עוקבים אחר אזורים אלה כדי לזהות תנועות מחיר אפשריות לעבר הנזילות.",related:["buy-side-liquidity","sell-side-liquidity","liquidity-sweep"]},{id:"liquidation",he:"ליקווידציה",en:"Liquidation",category:"risk",definition:"סגירה כפויה של פוזיציה על ידי הברוקר או מערכת ניהול הסיכונים, למשל בעקבות אי־עמידה בדרישות ביטחונות. הסגירה עשויה להתבצע ללא החלטה יזומה של הסוחר ובמחיר השוק הזמין."},{id:"liquidity-sweep",he:"לקיחת נזילות",en:"Liquidity Sweep",category:"ict",definition:"תנועת מחיר שחוצה רמת שיא או שפל שבה צפוי להימצא ריכוז פקודות. בשיטות ICT/SMC סוחרים עוקבים אחר התנהגות המחיר לאחר חציית הרמה, כדי לזהות המשך תנועה או היפוך אפשרי.",related:["buy-side-liquidity","sell-side-liquidity","liquidity-pool"]},{id:"macd",he:"מאקדי",en:"Moving Average Convergence Divergence – MACD",category:"technical",definition:"אינדיקטור מומנטום המבוסס על הקשר בין ממוצעים נעים מעריכיים, ומציג בדרך כלל קו MACD, קו איתות והיסטוגרמה. סוחרים משתמשים בו כדי לבחון שינויים במומנטום, הצטלבויות וסטיות אפשריות בין האינדיקטור למחיר."},{id:"macroeconomics",he:"מאקרו-כלכלה",en:"Macroeconomics",category:"macro",definition:"תחום העוסק בתהליכים כלכליים רחבים, כגון אינפלציה, ריבית, תעסוקה וצמיחה. סוחרי חוזים עתידיים עוקבים אחר נתונים מאקרו־כלכליים משום שהם עשויים להשפיע על כיוון השוק ועל התנודתיות."},{id:"market-structure",he:"מבנה שוק",en:"Market Structure",category:"technical",definition:"האופן שבו המחיר יוצר שיאים ושפלים לאורך זמן. משמש לזיהוי מגמות, טווחי מסחר ושינויים אפשריים בכיוון השוק, ומהווה מרכיב מרכזי בניתוח טכני ובשיטות ICT/SMC."},{id:"maximum-drawdown-maximum-loss-limit",he:"מגבלת הפסד מקסימלית",en:"Maximum Drawdown/Maximum Loss Limit",category:"prop",definition:"רמת ההפסד המרבית המותרת בחשבון בהתאם לכללי חברת המימון. המגבלה עשויה להיות קבועה או נגררת, וחריגה ממנה עלולה לגרום לפסילת החשבון.",related:["drawdown","trailing-drawdown"]},{id:"contract-limit",he:"מגבלת חוזים",en:"Contract Limit / Max Position Size",category:"prop",definition:"מספר החוזים המקסימלי שמותר להחזיק בבת אחת, בדרך כלל לפי גודל החשבון. ברוב החברות 10 חוזי מיקרו נספרים כחוזה מלא אחד, וחריגה מהמגבלה יכולה להוביל לסגירת פוזיציות או לפסילה.",related:["e-mini-futures-contract","micro-futures-contract","scaling-plan"]},{id:"account-limit",he:"מגבלת חשבונות",en:"Account Limit",category:"prop",definition:"מספר החשבונות המקסימלי שסוחר אחד יכול להחזיק במקביל באותה חברת מימון. המגבלה משתנה בין החברות, ולפעמים יש מגבלה נפרדת לחשבונות הערכה ולחשבונות ממומנים.",related:["evaluation-account","funded-account"]},{id:"cme-price-limit",he:"מגבלת מחיר של CME",en:"CME Price Limits",category:"futures",definition:"גבולות שהבורסה קובעת לכמה המחיר של חוזה יכול לזוז בפרק זמן מסוים. כשהמחיר מגיע לגבול, המסחר נעצר לזמן קצר או מוגבל. ב-ES וב-NQ זה קורה רק בימים של תנועות קיצוניות.",related:["futures-contract","volatility"]},{id:"downtrend",he:"מגמת ירידה",en:"Downtrend",category:"technical",definition:"מצב שבו המחיר נע באופן כללי כלפי מטה, ומתאפיין לרוב ברצף של שיאים ושפלים יורדים. סוחרים משתמשים במבנה המגמה כדי לזהות את כיוון השוק ולחפש הזדמנויות מכירה."},{id:"uptrend",he:"מגמת עלייה",en:"Uptrend",category:"technical",definition:"מצב שבו המחיר נע באופן כללי כלפי מעלה, ומתאפיין לרוב ברצף של שיאים ושפלים עולים. סוחרים משתמשים במבנה המגמה כדי לזהות את כיוון השוק ולחפש הזדמנויות קנייה."},{id:"personal-consumption-expenditures-price-index",he:"מדד המחירים להוצאה לצריכה פרטית",en:"Personal Consumption Expenditures Price Index - PCE",category:"macro",definition:"מדד אינפלציה אמריקאי המודד שינויים במחירי מוצרים ושירותים הנצרכים על ידי משקי בית. מדד הליבה שלו הוא אחד המדדים המרכזיים שהפדרל ריזרב בוחן בהערכת האינפלציה.",related:["consumer-price-index","inflation","core-inflation"]},{id:"consumer-price-index",he:"מדד המחירים לצרכן",en:"Consumer Price Index - CPI",category:"macro",definition:"מדד המודד את השינוי במחירי סל מוצרים ושירותים לצרכנים. פרסום נתוני CPI בארצות הברית עשוי להשפיע על ציפיות הריבית ולגרום לתנודתיות משמעותית בחוזים עתידיים.",related:["personal-consumption-expenditures-price-index","inflation","core-inflation"],links:[{type:"video",id:"economic-news"}]},{id:"money-flow-index",he:"מדד זרימת הכסף",en:"Money Flow Index - MFI",category:"technical",definition:"אינדיקטור מומנטום שמשלב מחיר ונפח מסחר כדי להעריך את עוצמת לחץ הקנייה והמכירה. הוא נע בסולם שבין 0 ל־100 ומשמש בין היתר לזיהוי מצבים אפשריים של קניית יתר, מכירת יתר וסטיות."},{id:"purchasing-managers-index",he:"מדד מנהלי הרכש",en:"Purchasing Managers' Index - PMI",category:"macro",definition:"מדד המבוסס על סקרים בקרב מנהלי רכש ומספק תמונת מצב לגבי הפעילות הכלכלית במגזר מסוים. פרסומו עשוי להשפיע על ציפיות המשקיעים ועל התנודתיות בשווקים."},{id:"nasdaq-100-index",he:"מדד נאסד״ק 100",en:"Nasdaq-100 Index - NDX",category:"futures",definition:"מדד הכולל מאה מהחברות הלא־פיננסיות הגדולות הנסחרות בבורסת נאסד״ק, בהתאם לכללי המדד. סוחרי חוזים עתידיים יכולים לסחור בתנועות המדד באמצעות חוזי NQ ו-MNQ."},{id:"russell-2000-index",he:"מדד ראסל 2000",en:"Russell 2000 Index - RUT",category:"futures",definition:"מדד מניות אמריקאי המייצג חברות בעלות שווי שוק קטן יחסית מתוך מדד Russell 3000. ניתן לסחור בתנועותיו באמצעות חוזי RTY ו־M2K."},{id:"s-p-500-index",he:"מדד S&P 500",en:"S&P 500 Index - SPX",category:"futures",definition:"מדד מניות אמריקאי הכולל חמש מאות חברות מובילות הנבחרות לפי קריטריונים מוגדרים. סוחרי חוזים עתידיים עוקבים אחריו וסוחרים בתנועותיו באמצעות חוזי ES ו־MES."},{id:"payout-cycle",he:"מחזור משיכה",en:"Payout Cycle",category:"prop",definition:"התקופה או רצף התנאים שלפיהם סוחר יכול להגיש בקשה למשיכת רווחים מחשבון ממומן. מחזור המשיכה עשוי להיות מבוסס על ימי מסחר, תאריכים קבועים או תנאי זכאות אחרים, בהתאם לחברה ולמסלול."},{id:"profit-taking",he:"מימוש רווחים",en:"Profit Taking",category:"risk",definition:"סגירת פוזיציה רווחית, במלואה או בחלקה, כדי להפוך רווח שטרם מומש לרווח ממומש. סוחרים עשויים לממש רווחים בהגעה ליעד מחיר או בהתאם לכללי ניהול העסקה."},{id:"leverage",he:"מינוף",en:"Leverage",category:"risk",definition:"אפשרות לשלוט בחשיפה כספית גדולה יחסית באמצעות סכום ביטחונות קטן יותר. במסחר בחוזים עתידיים המינוף מגדיל את ההשפעה של תנועות מחיר על הרווח וההפסד, ולכן מחייב ניהול סיכונים קפדני."},{id:"minimum-payout",he:"מינימום משיכה",en:"Minimum Payout / Minimum Withdrawal",category:"prop",definition:"הסכום הנמוך ביותר שניתן לבקש למשוך מחשבון ממומן, בכפוף לתנאי החברה. יש להבחין בינו לבין יתרת הביטחון שנדרשת להישאר בחשבון או סכום הרווח הדרוש כדי להיות זכאי למשיכה."},{id:"averaging-down",he:"מיצוע הפסדים/DCA",en:"Averaging Down/Dollar-Cost Averaging",category:"risk",definition:"הוספת יחידות לפוזיציה כאשר המחיר נע נגד כיוון העסקה, במטרה לשנות את מחיר הכניסה הממוצע. במסחר בחוזים עתידיים הפעולה עלולה להגדיל את החשיפה ואת ההפסד האפשרי, וחברות מימון מסוימות מגבילות אותה."},{id:"micro-scalping",he:"מיקרו סקאלפינג",en:"Micro Scalping",category:"performance",definition:"סגנון מסחר המתמקד בעסקאות קצרות מאוד ובניסיון להרוויח מתנועות מחיר קטנות במיוחד. בחלק מחברות המימון קיימות מגבלות על עסקאות קצרות במיוחד או על דפוסי מסחר מסוימים, ולכן חשוב לבדוק את ההגדרה הספציפית של החברה."},{id:"recession",he:"מיתון",en:"Recession",category:"macro",definition:"תקופה של ירידה משמעותית בפעילות הכלכלית, הנבחנת באמצעות מדדים כגון תעסוקה, ייצור, הכנסה ותוצר. ציפיות למיתון עשויות להשפיע על מדדי המניות, הריביות והחוזים העתידיים."},{id:"aggressive-selling",he:"מכירה אגרסיבית",en:"Aggressive Selling",category:"orderflow",definition:"ביצוע פקודות מכירה מול פקודות קנייה ממתינות בצד ה־Bid. בניתוח Order Flow, פעילות מכירה אגרסיבית עשויה להצביע על לחץ מצד מוכרים, אך אינה מבטיחה שהמחיר ימשיך לרדת.",related:["aggressive-buying","passive-buying","absorption"]},{id:"short-selling-short-position",he:"מכירה בחסר",en:"Short Selling/Short Position",category:"fundamentals",definition:"פתיחת פוזיציה שמרוויחה מירידת מחיר הנכס. במסחר בחוזים עתידיים ניתן לפתוח פוזיציית שורט באמצעות מכירת חוזה, ללא צורך בהשאלת מניות כפי שנדרש בדרך כלל בשורט על מניות.",related:["long-position"]},{id:"contract-multiplier",he:"מכפיל חוזה",en:"Contract Multiplier",category:"futures",definition:"הגורם הקובע את השווי הכספי של כל נקודת תנועה בחוזה עתידי. לדוגמה, בחוזה NQ כל נקודת מדד שווה 20 דולר לחוזה, ואילו ב־MNQ היא שווה 2 דולר."},{id:"moving-average",he:"ממוצע נע",en:"Moving Average - MA",category:"technical",definition:"אינדיקטור המציג את ממוצע המחירים לאורך מספר תקופות מוגדר. משמש לזיהוי כיוון מגמה, לבחינת מומנטום ולזיהוי אזורי תגובה אפשריים של המחיר.",related:["exponential-moving-average","simple-moving-average"]},{id:"exponential-moving-average",he:"ממוצע נע אקספוננציאלי",en:"Exponential Moving Average - EMA",category:"technical",definition:"סוג של ממוצע נע המעניק משקל גבוה יותר לנתוני המחיר האחרונים. בשל כך הוא מגיב בדרך כלל מהר יותר לשינויים במחיר בהשוואה לממוצע נע פשוט באותו אורך.",related:["moving-average","simple-moving-average"]},{id:"simple-moving-average",he:"ממוצע נע פשוט",en:"Simple Moving Average - SMA",category:"technical",definition:"ממוצע המחושב באמצעות סכימת מחירי מספר תקופות וחלוקתם במספר התקופות. משמש לניתוח מגמות ולהשוואת המחיר הנוכחי לממוצע ההיסטורי.",related:["moving-average","exponential-moving-average"]},{id:"algorithmic-trading",he:"מסחר אלגוריתמי",en:"Algorithmic Trading",category:"platforms",definition:"מסחר המבוסס על מערכת כללים ממוחשבת המייצרת אותות או מבצעת פקודות בהתאם לתנאים שנקבעו מראש. בחברות מימון עשויות לחול מגבלות על שימוש באלגוריתמים ובמערכות מסחר אוטומטיות."},{id:"news-trading",he:"מסחר בחדשות",en:"News Trading",category:"macro",definition:"פתיחת עסקאות או ניהולן סביב פרסום נתונים כלכליים ואירועים בעלי השפעה אפשרית על השוק. פרסומים כאלה עשויים לגרום לתנודתיות חדה, ובחברות מימון מסוימות קיימות מגבלות על מסחר בסמוך אליהם.",links:[{type:"video",id:"news-trading"},{type:"route",to:"/economic-calendar",label:"לוח שנה כלכלי"}]},{id:"high-frequency-trading",he:"מסחר בתדירות גבוהה",en:"High-Frequency Trading - HFT",category:"platforms",definition:"שיטת מסחר אוטומטית המבוססת על שליחת פקודות רבות במהירות גבוהה מאוד, תוך שימוש במערכות ובתשתיות טכנולוגיות מתקדמות. חברות מימון מסוימות מגבילות או אוסרות פעילות מסוג זה בהתאם לכללי המסלול."},{id:"day-trading",he:"מסחר יומי",en:"Day Trading",category:"performance",definition:"שיטת מסחר שבה פותחים וסוגרים פוזיציות במהלך אותו יום מסחר, ללא החזקתן לטווח ארוך. במסחר בחוזים עתידיים יש להתחשב בשעות הפעילות ובכללי סגירת הפוזיציות של הברוקר או חברת המימון."},{id:"overtrading",he:"מסחר יתר",en:"Overtrading",category:"performance",definition:"מצב שבו סוחר מבצע עסקאות בתדירות, בכמות או ברמת סיכון החורגות מתוכנית המסחר שלו. התופעה עשויה לנבוע מרצון לפצות על הפסדים, מפחד להחמיץ הזדמנויות או מקבלת החלטות אימפולסיבית."},{id:"revenge-trading",he:"מסחר נקמה",en:"Revenge Trading",category:"performance",definition:"דפוס התנהגות שבו סוחר פותח עסקאות מתוך רצון להחזיר במהירות הפסדים קודמים, במקום לפעול לפי תוכנית המסחר. התנהלות כזו עלולה להוביל להגדלת סיכונים, למסחר יתר ולחריגה מכללי ניהול הסיכונים."},{id:"swing-trading",he:"מסחר סווינג",en:"Swing Trading",category:"performance",definition:"שיטת מסחר שבה מחזיקים פוזיציות במשך מספר ימים או יותר כדי לנצל תנועות מחיר רחבות יחסית. בחברות מימון מסוימות קיימות מגבלות על החזקת פוזיציות מעבר לסיום יום המסחר."},{id:"heatmap",he:"מפת חום",en:"Heatmap",category:"orderflow",definition:"תצוגה ויזואלית המציגה את ריכוזי הנזילות בספר הפקודות לאורך זמן וברמות מחיר שונות, בדרך כלל באמצעות צבעים בעוצמות משתנות. היא מאפשרת לזהות אזורים שבהם ממתינות פקודות לימיט רבות ולעקוב אחר הוספה או ביטול שלהן, אך אינה מבטיחה שהפקודות אכן יבוצעו."},{id:"plugin-mode",he:"מצב פלאגין",en:"Plugin Mode",category:"platforms",definition:"מצב עבודה שבו תוכנה או כלי מסחר פועלים כתוסף המשולב במערכת אחרת, במקום כממשק עצמאי. המשמעות המדויקת תלויה בתוכנה, ויכולה לכלול קבלת נתונים, שליחת פקודות או הרחבת יכולות הפלטפורמה הראשית."},{id:"liquidity",he:"נזילות",en:"Liquidity",category:"technical",definition:"היכולת לבצע עסקאות בשוק במהירות ובכמות הרצויה, ללא השפעה משמעותית על המחיר. בשיטות ICT/SMC המונח משמש גם לתיאור אזורים שבהם צפוי להימצא ריכוז פקודות, כגון מעל שיאים ומתחת לשפלים."},{id:"external-range-liquidity",he:"נזילות חיצונית",en:"External Range Liquidity - ERL",category:"ict",definition:"בשיטות ICT/SMC, נזילות הנמצאת מעבר לגבולות של טווח מחירים מוגדר, בדרך כלל מעל השיא או מתחת לשפל של הטווח. סוחרים עשויים להתייחס לרמות אלה כיעדים אפשריים לתנועת המחיר.",related:["internal-range-liquidity"]},{id:"sell-side-liquidity",he:"נזילות מכירה",en:"Sell-Side Liquidity - SSL",category:"ict",definition:"בשיטות ICT/SMC, אזור שבו צפוי להימצא ריכוז של פקודות מכירה, לרוב מתחת לשפלים קודמים. פקודות אלה עשויות לכלול סטופים של סוחרים בפוזיציות לונג ופקודות כניסה של סוחרי פריצה.",related:["buy-side-liquidity","liquidity-sweep","liquidity-pool"]},{id:"internal-range-liquidity",he:"נזילות פנימית",en:"Internal Range Liquidity - IRL",category:"ict",definition:"בשיטות ICT/SMC, נזילות או אזורי חוסר איזון הנמצאים בתוך טווח מחירים מוגדר. סוחרים בוחנים כיצד המחיר נע בין אזורים פנימיים לבין רמות נזילות שמחוץ לטווח.",related:["external-range-liquidity"]},{id:"buy-side-liquidity",he:"נזילות קנייה",en:"Buy-Side Liquidity - BSL",category:"ict",definition:"בשיטות ICT/SMC, אזור שבו צפוי להימצא ריכוז של פקודות קנייה, לרוב מעל שיאים קודמים. פקודות אלה עשויות לכלול סטופים של סוחרים בפוזיציות שורט ופקודות כניסה של סוחרי פריצה.",related:["sell-side-liquidity","liquidity-sweep","liquidity-pool"]},{id:"risk-management",he:"ניהול סיכונים",en:"Risk Management",category:"risk",definition:"מערכת כללים שמגדירה כמה הון הסוחר מוכן לסכן בכל עסקה ובכל יום מסחר. כוללת בין היתר קביעת סטופ לוס, גודל פוזיציה, מגבלות הפסד ויחס סיכון־סיכוי.",links:[{type:"video",id:"risk-management"}]},{id:"trade-management",he:"ניהול עסקה",en:"Trade Management",category:"risk",definition:"הפעולות שמבצע הסוחר לאחר פתיחת פוזיציה ועד לסגירתה. עשויות לכלול הזזת סטופ, מימוש חלקי, הגדלת פוזיציה או יציאה בהתאם לתוכנית המסחר."},{id:"automated-trade-management",he:"ניהול עסקה אוטומטי",en:"Automated Trade Management - ATM",category:"risk",definition:"מנגנון בפלטפורמת מסחר שמאפשר להגדיר מראש פעולות לניהול פוזיציה, כגון סטופ-לוס, יעד רווח, סטופ נגרר והעברת סטופ לנקודת הכניסה. יכולות המנגנון משתנות בין פלטפורמות, ו־ATM אינו מבטיח ביצוע במחיר המבוקש."},{id:"ninjatrader",he:"נינג'ה טריידר",en:"NinjaTrader",category:"platforms",definition:"פלטפורמת מסחר המתמקדת בחוזים עתידיים ומציעה גרפים, אינדיקטורים, ניהול פקודות וכלים לניתוח אסטרטגיות. היא מאפשרת גם שימוש בכלים מותאמים אישית ובמסחר אוטומטי, בהתאם לחיבור ולתצורת המשתמש."},{id:"manual-trading-lockout",he:"נעילה ידנית של המסחר",en:"Manual Trading Lockout",category:"risk",definition:"פעולה יזומה שמגבילה או חוסמת את האפשרות לפתוח עסקאות חדשות בחשבון, בדרך כלל לצורך ניהול סיכונים ומשמעת מסחר. אופן ההפעלה, משך הנעילה והאפשרות לבטל אותה תלויים בפלטפורמה או במערכת ניהול הסיכונים."},{id:"stop-loss-locking",he:"נעילת סטופ",en:"Stop-Loss Locking/Stop-Loss Requirement",category:"risk",definition:"מנגנון או כלל המחייב שימוש בפקודת סטופ-לוס, ולעיתים מגביל את האפשרות להסיר אותה או להרחיק אותה לאחר פתיחת העסקה. יש לבדוק את משמעות המונח בכל חברה או פלטפורמה, משום שהוא אינו מציין כלל אחיד בענף."},{id:"point-of-control",he:"נקודת שליטה",en:"Point of Control - POC",category:"orderflow",definition:"רמת המחיר שבה התרכז נפח המסחר הגבוה ביותר בטווח שנבחר ב-Volume Profile. משמשת לזיהוי רמת פעילות מרכזית ולבחינת תגובת המחיר כאשר הוא חוזר אליה.",related:["value-area","value-area-high","value-area-low","volume-profile","previous-point-of-control"]},{id:"previous-point-of-control",he:"נקודת שליטה קודמת",en:"Previous Point of Control - PPOC",category:"orderflow",definition:"רמת ה-POC של תקופת מסחר קודמת, למשל יום המסחר הקודם. סוחרים עשויים לעקוב אחריה כרמת ייחוס אפשרית לתגובת מחיר או להמשך תנועה.",related:["value-area","value-area-high","value-area-low","point-of-control","volume-profile"]},{id:"engulfing-candlestick",he:"נר בולען",en:"Engulfing Candlestick",category:"technical",definition:"תבנית של שני נרות שבה גוף הנר השני מכסה את גוף הנר הקודם, בהתאם להגדרת התבנית. סוחרים משתמשים בה לזיהוי שינוי אפשרי בלחץ הקנייה או המכירה."},{id:"doji-candlestick",he:"נר דוג׳י",en:"Doji Candlestick",category:"technical",definition:"נר יפני שבו מחיר הפתיחה ומחיר הסגירה קרובים מאוד זה לזה. עשוי להצביע על איזון יחסי בין קונים למוכרים או על חוסר החלטיות, אך משמעותו תלויה במיקום הנר ובהקשר השוק."},{id:"marubozu-candlestick",he:"נר מרובוזו",en:"Marubozu Candlestick",category:"technical",definition:"נר יפני בעל גוף גדול ופתילים קטנים מאוד או ללא פתילים. עשוי להצביע על לחץ קנייה או מכירה משמעותי במהלך התקופה שאותה הוא מייצג."},{id:"inside-bar",he:"נר פנימי",en:"Inside Bar",category:"technical",definition:"נר שהטווח שלו נמצא כולו בתוך הטווח של הנר הקודם. עשוי להצביע על הצטמצמות זמנית בתנודתיות, וסוחרים לעיתים עוקבים אחר פריצת גבולותיו."},{id:"swing-high",he:"סווינג היי",en:"Swing High",category:"technical",definition:"נקודת שיא מקומית בגרף, שבה המחיר הגיע לרמה גבוהה ביחס לנרות הסמוכים ולאחר מכן ירד. משמשת לזיהוי מבנה השוק, רמות התנגדות אפשריות ואזורי נזילות.",related:["swing-low"]},{id:"swing-low",he:"סווינג לואו",en:"Swing Low",category:"technical",definition:"נקודת שפל מקומית בגרף, שבה המחיר הגיע לרמה נמוכה ביחס לנרות הסמוכים ולאחר מכן עלה. משמשת לזיהוי מבנה השוק, רמות תמיכה אפשריות ואזורי נזילות.",related:["swing-high"]},{id:"daily-stop",he:"סטופ יומי",en:"Daily Stop",category:"risk",definition:"מגבלת הפסד שסוחר מגדיר לעצמו עבור יום מסחר, כחלק מתוכנית ניהול הסיכונים האישית שלו. הגעה למגבלה מחייבת הפסקת מסחר בהתאם לכללים שהסוחר קבע, גם כאשר חברת המימון מאפשרת להמשיך לסחור.",related:["daily-loss-limit","loss-limit"],links:[{type:"article",slug:"rithmic-daily-stop"},{type:"article",slug:"tradovate-daily-stop"},{type:"video",id:"intraday-stop-trading"}]},{id:"stop-loss",he:"סטופ לוס",en:"SL – Stop Loss",category:"fundamentals",definition:"פקודה שנועדה להגביל הפסד באמצעות יציאה מפוזיציה כאשר המחיר מגיע לרמה שהוגדרה מראש. ביצוע הפקודה אינו מבטיח יציאה במחיר המדויק, במיוחד בזמן תנודתיות גבוהה.",related:["take-profit","bracket-order","break-even"]},{id:"stop-limit-order",he:"סטופ לימיט",en:"Stop Limit Order",category:"fundamentals",definition:"פקודה שמפעילה פקודת Limit כאשר המחיר מגיע לרמת סטופ מוגדרת. מאפשרת לקבוע מחיר ביצוע מינימלי או מקסימלי, אך אינה מבטיחה שהפקודה תתבצע אם השוק ינוע מעבר למחיר הלימיט.",related:["market-order","limit-order","stop-market-order"],links:[{type:"video",id:"trading-orders"}]},{id:"stop-market-order",he:"סטופ מרקט",en:"Stop Market Order",category:"fundamentals",definition:"פקודה שהופכת לפקודת Market כאשר המחיר מגיע לרמת הסטופ שהוגדרה. מיועדת לתת עדיפות לביצוע, אך המחיר בפועל עשוי להיות שונה ממחיר ההפעלה.",related:["market-order","limit-order","stop-limit-order"],links:[{type:"video",id:"trading-orders"}]},{id:"trailing-stop",he:"סטופ נגרר",en:"Trailing Stop",category:"fundamentals",definition:"פקודת סטופ שרמתה מתעדכנת בעקבות תנועת המחיר בכיוון הרצוי, בהתאם למרחק או לכללים שהוגדרו. משמשת להגנה על רווחים או לצמצום סיכון במהלך עסקה פתוחה."},{id:"eod-trailing-drawdown",he:"סטופ סוף יום (EOD)",en:"End of Day (EOD) Trailing Drawdown",category:"prop",definition:"סוג של דרודאון נגרר שבו קו ההפסד מתעדכן רק לפי היתרה בסגירת יום המסחר. רווח פתוח במהלך היום לא מזיז את הקו, והעדכון חל מיום המסחר הבא. במהלך היום החשבון נבדק מול הקו שנקבע בסגירה הקודמת.",related:["trailing-drawdown","intraday-trailing-drawdown","drawdown"],links:[{type:"video",id:"eod-trailing"},{type:"article",slug:"tradovate-drawdown"}]},{id:"intraday-trailing-drawdown",he:"סטופ תוך יומי (Intraday)",en:"Intraday Trailing Drawdown",category:"prop",definition:"סוג של דרודאון נגרר שבו קו ההפסד עולה בזמן אמת לפי השיא של שווי החשבון, כולל רווח פתוח בעסקאות שעדיין לא נסגרו. אם עסקה הגיעה לרווח פתוח גבוה ואז חזרה אחורה, הקו כבר עלה ונשאר למעלה, ולכן הנסיגה יכולה לפסול את החשבון גם בלי הפסד בפועל.",related:["trailing-drawdown","eod-trailing-drawdown","drawdown"],links:[{type:"video",id:"intraday-trailing"},{type:"article",slug:"tradovate-drawdown"}]},{id:"divergence",he:"סטייה",en:"Divergence",category:"technical",definition:"מצב שבו תנועת המחיר אינה תואמת את התנועה של אינדיקטור או מדד אחר. לדוגמה, המחיר יוצר שיא חדש בעוד שה-RSI אינו יוצר שיא מקביל, מצב שעשוי להצביע על היחלשות המומנטום."},{id:"smt-divergence",he:"סטייה בין שווקים",en:"SMT Divergence",category:"ict",definition:"מושג בשיטות ICT/SMC המתאר חוסר התאמה בין תנועות של שני שווקים בעלי מתאם, כגון NQ ו-ES. לדוגמה, כאשר שוק אחד יוצר שיא חדש והשני אינו מאשר אותו, סוחרים עשויים לפרש זאת כסימן אפשרי לשינוי בהתנהגות המחיר."},{id:"standard-deviation",he:"סטיית תקן",en:"Standard Deviation",category:"technical",definition:"מדד סטטיסטי המתאר את מידת הפיזור של נתונים ביחס לממוצע שלהם. בניתוח שוק משתמשים בו בין היתר למדידת תנודתיות, לבניית רצועות מחיר ולהערכת חריגות של המחיר ביחס להתנהגותו בתקופה שנבדקה."},{id:"cqg",he:"סי-קיו-ג'י",en:"CQG",category:"platforms",definition:"חברה המספקת נתוני שוק, קישוריות לביצוע פקודות וכלים טכנולוגיים למסחר, בין היתר בשוק החוזים העתידיים. שירותיה משמשים ברוקרים ופלטפורמות מסחר שונות, בהתאם להסכמי החיבור והנתונים."},{id:"slippage",he:"סליפג'/החלקה",en:"Slippage",category:"fundamentals",definition:"ההפרש בין המחיר שרצית לבין המחיר שבו הפקודה בוצעה בפועל. קורה בעיקר בפקודות מרקט ובסטופים, בזמן חדשות או כשאין נזילות. בחשבון ממומן, סליפג' יכול להוסיף הפסד מעבר למה שתכננת ולקרב אותך לדרודאון.",related:["market-order","stop-market-order","volatility"]},{id:"absorption",he:"ספיגה",en:"Absorption",category:"orderflow",definition:"מצב שבו פקודות קנייה או מכירה אגרסיביות מבוצעות מול נזילות נגדית, מבלי שהמחיר מתקדם באופן משמעותי בכיוון הלחץ. בניתוח Order Flow, ספיגה עשויה להצביע על נוכחות של פקודות פסיביות גדולות ברמת מחיר מסוימת.",related:["aggressive-buying","aggressive-selling","passive-buying"]},{id:"order-book",he:"ספר פקודות",en:"Order Book",category:"fundamentals",definition:"מערכת המציגה פקודות קנייה ומכירה ממתינות ברמות מחיר שונות. משמשת לבחינת עומק השוק והנזילות הגלויה, אך אינה מציגה בהכרח את כל הכוונות או הפקודות הנסתרות של המשתתפים."},{id:"scalping",he:"סקאלפינג",en:"Scalping",category:"performance",definition:"סגנון מסחר המתמקד בעסקאות קצרות יחסית, לעיתים של שניות או דקות, במטרה לנצל תנועות מחיר קטנות. דורש תשומת לב לעלויות מסחר, למהירות הביצוע ולניהול הסיכונים."},{id:"asian-trading-session",he:"סשן אסיה",en:"Asian Trading Session",category:"futures",definition:"פרק פעילות המסחר בשווקים האסייתיים, בעיקר בשעות הלילה לפי שעון ישראל. במסחר בחוזים עתידיים על מדדי ארה״ב, הסשן מתאפיין לעיתים בנזילות ובתנודתיות נמוכות יחסית לסשן ניו יורק. סוחרי ICT/SMC עוקבים אחר השיא והשפל של הסשן כאזורי נזילות אפשריים.",related:["trading-session","london-trading-session","new-york-session"]},{id:"london-trading-session",he:"סשן לונדון",en:"London Trading Session",category:"futures",definition:"פרק פעילות המסחר בשווקים האירופיים, המתחיל בשעות הבוקר לפי שעון ישראל. הסשן מתאפיין לעיתים בעלייה בנפחי המסחר ובתנודתיות ביחס לסשן אסיה. סוחרי ICT/SMC עוקבים אחר תנועות המחיר בסשן, במיוחד ביחס לטווח המחירים שנוצר במהלך סשן אסיה.",related:["trading-session","asian-trading-session","new-york-session"]},{id:"trading-session",he:"סשן מסחר",en:"Trading Session",category:"futures",definition:"פרק זמן מוגדר של פעילות בשוק, כגון הסשן האסייתי, האירופי או האמריקאי. במסחר בחוזים עתידיים סוחרים בוחנים את מאפייני התנודתיות והנזילות בשעות השונות.",related:["asian-trading-session","london-trading-session","new-york-session"]},{id:"new-york-session",he:"סשן ניו יורק",en:"New York Session",category:"futures",definition:"פרק הפעילות בשוק האמריקאי, שבו מתקיימת בין היתר פתיחת המסחר הרגיל במניות בארצות הברית. סוחרי חוזים עתידיים על מדדי מניות עוקבים אחריו בשל נפחי המסחר והתנודתיות שעשויים להתגבר בשעות אלה.",related:["trading-session","asian-trading-session","london-trading-session"]},{id:"market-depth",he:"עומק שוק",en:"Market Depth",category:"fundamentals",definition:"כמות פקודות הקנייה והמכירה הממתינות ברמות מחיר שונות בספר הפקודות. עומק השוק מאפשר לסוחרים להעריך את הנזילות הגלויה ואת היכולת לבצע עסקאות בכמויות שונות ללא תזוזת מחיר משמעותית."},{id:"osek-patur",he:"עוסק פטור",en:"Exempt Dealer (Osek Patur)",category:"tax",definition:'תיק עסק לעסק קטן שהמחזור השנתי שלו מתחת לתקרה שנקבעת כל שנה. עוסק פטור לא גובה מע"מ, אבל עדיין מדווח על ההכנסות ומשלם מס הכנסה וביטוח לאומי. אם אתה מקבל משיכות, תבדוק עם רואה חשבון אם זה המסלול שמתאים לך.',related:["annual-tax-report","recognized-expenses"]},{id:"market-makers",he:"עושי שוק",en:"Market Makers",category:"fundamentals",definition:"משתתפים בשוק המספקים נזילות באמצעות הצבת פקודות קנייה ומכירה. פעילותם מסייעת לביצוע עסקאות ולצמצום מרווחי המחירים, אך אינה מבטיחה נזילות קבועה בכל מצב שוק."},{id:"trading-commission",he:"עמלת מסחר",en:"Trading Commission",category:"fundamentals",definition:"תשלום הנגבה עבור ביצוע עסקאות באמצעות ברוקר או פלטפורמת מסחר. בחוזים עתידיים העמלות מחושבות בדרך כלל לפי מספר החוזים והפעולות, ועשויות לכלול גם עמלות בורסה וסליקה."},{id:"closed-positions",he:"עסקאות סגורות",en:"Closed Positions",category:"fundamentals",definition:"פוזיציות שהסוחר סיים את החזקתן באמצעות ביצוע פעולה נגדית או סגירה במערכת המסחר. לאחר סגירת העסקה, הרווח או ההפסד שלה הופכים לממומשים."},{id:"open-positions",he:"עסקאות פתוחות",en:"Open Positions",category:"fundamentals",definition:"פוזיציות מסחר שטרם נסגרו במלואן. כל עוד הפוזיציה פתוחה, הרווח או ההפסד שלה משתנים בהתאם לתנועת המחיר בשוק."},{id:"trading-consistency",he:"עקביות במסחר",en:"Trading Consistency",category:"prop",definition:"מידת היציבות של ביצועי הסוחר לאורך עסקאות וימי מסחר. בחברות מימון מסוימות קיימים כללי עקביות המגבילים את חלקו של יום רווחי מסוים מתוך הרווח הכולל לצורך עמידה בתנאי המסלול או המשיכה.",links:[{type:"video",id:"consistency-rule"},{type:"route",to:"/calculators",label:"מחשבון עקביות"}]},{id:"equity-curve",he:"עקומת הון",en:"Equity Curve",category:"performance",definition:"גרף המציג את השינוי בהון החשבון לאורך זמן בעקבות תוצאות המסחר. משמש להערכת ביצועי אסטרטגיה, זיהוי תקופות של ירידה בהון ובחינת יציבות התוצאות.",links:[{type:"article",slug:"journal-statistics-1-to-1"}]},{id:"point-value",he:"ערך נקודה",en:"Point Value",category:"futures",definition:"השווי הכספי של תזוזה בנקודה אחת בחוזה עתידי בודד. לדוגמה, בחוזה MNQ כל נקודה שווה 2 דולר, ובחוזה NQ כל נקודה שווה 20 דולר."},{id:"federal-reserve",he:"פד",en:"Federal Reserve - Fed",category:"macro",definition:"הבנק המרכזי של ארצות הברית, האחראי בין היתר על המדיניות המוניטרית. החלטות הריבית והודעות הפד עשויות להשפיע משמעותית על מדדי המניות, איגרות החוב והחוזים העתידיים.",related:["federal-funds-rate","interest-rate-expectations"]},{id:"position",he:"פוזיציה",en:"Position",category:"fundamentals",definition:"חשיפה פעילה לנכס פיננסי בעקבות פתיחת עסקת קנייה או מכירה. במסחר בחוזים עתידיים הפוזיציה יכולה להיות לונג או שורט, והרווח או ההפסד שלה משתנים בהתאם לתנועת המחיר."},{id:"pullback",he:"פולבק",en:"Pullback",category:"technical",definition:"תנועה זמנית של המחיר נגד הכיוון של המהלך הקודם, ללא שינוי הכרחי במגמה המרכזית. סוחרים משתמשים בפולבקים כדי לחפש נקודות כניסה אפשריות בכיוון המגמה. נקרא גם תיקון (Retracement)."},{id:"fear-of-missing-out",he:"פומו",en:"Fear of Missing Out - FOMO",category:"performance",definition:"חשש להחמיץ הזדמנות מסחר, שעלול לגרום לכניסה מאוחרת או לא מתוכננת לעסקה. במסחר יומי פומו עשוי להוביל לחריגה מכללי האסטרטגיה וניהול הסיכונים."},{id:"fibonacci-retracement",he:"פיבונאצ׳י",en:"Fibonacci Retracement",category:"technical",definition:"כלי ניתוח טכני המציג רמות תיקון יחסיות בין שתי נקודות מחיר שנבחרו בגרף. סוחרים משתמשים בו לזיהוי אזורי תגובה אפשריים במהלך תיקון או המשך מגמה.",related:["fibonacci-extension"],links:[{type:"video",id:"fibonacci-pivots"}]},{id:"fibonacci-extension",he:"פיבונאצ׳י אקסטנשן",en:"Fibonacci Extension",category:"technical",definition:"כלי המציג רמות מחיר אפשריות מעבר לטווח תנועה שנבחר, באמצעות יחסי פיבונאצ׳י. משמש בעיקר להערכת יעדי מחיר פוטנציאליים לאחר פריצה או המשך מגמה.",related:["fibonacci-retracement"]},{id:"pivot-point",he:"פיווט פוינט",en:"Pivot Point",category:"technical",definition:"רמת ייחוס המחושבת בדרך כלל מנתוני המחיר של תקופת מסחר קודמת, כגון הגבוה, הנמוך והסגירה. משמשת לזיהוי רמות תמיכה והתנגדות אפשריות במהלך המסחר.",links:[{type:"video",id:"fibonacci-pivots"}]},{id:"pine-script",he:"פיין סקריפט",en:"Pine Script",category:"platforms",definition:"שפת תכנות שפותחה עבור TradingView ומאפשרת ליצור אינדיקטורים, אסטרטגיות והתראות מותאמות אישית. באמצעותה ניתן לבצע חישובים על נתוני גרפים ולבחון רעיונות מסחר בסביבת הפלטפורמה."},{id:"paypal",he:"פייפאל",en:"PayPal",category:"fundamentals",definition:"שירות תשלומים דיגיטלי המאפשר שליחה וקבלה של כספים באמצעות חשבון מקוון. הוא משמש לתשלומים בינלאומיים ולעסקאות באינטרנט, כאשר זמינות השירות, העמלות ואפשרויות המשיכה תלויות במדינה ובסוג החשבון."},{id:"trading-platform",he:"פלטפורמת מסחר",en:"Trading Platform",category:"platforms",definition:"תוכנה המשמשת לצפייה בנתוני שוק, ניתוח גרפים, שליחת פקודות וניהול פוזיציות. בחוזים עתידיים קיימות פלטפורמות כגון Tradovate, NinjaTrader ו־Quantower, בהתאם לחיבורי הברוקר או חברת המימון.",links:[{type:"route",to:"/platforms",label:"פלטפורמות מסחר"}]},{id:"market-replay",he:"פלייבק/ריפליי",en:"Replay/Market Replay",category:"platforms",definition:"פונקציה המאפשרת לצפות בתנועות שוק היסטוריות באופן הדרגתי, לצורך תרגול וניתוח החלטות מסחר. בחלק מהפלטפורמות ניתן גם לבצע עסקאות מדומות במהלך השחזור ולבדוק את תוצאותיהן."},{id:"plane",he:"פליין",en:"Plane",category:"fundamentals",definition:"פלטפורמה לניהול תשלומים בינלאומיים לעובדים ולקבלנים, המאפשרת קבלת תשלומים במטבעות שונים. היא עשויה לשמש גם להעברת תגמולים לסוחרים דרך חברות התומכות בשירות, בכפוף לתנאי התשלום ולזמינות במדינת המקבל."},{id:"position-flipping",he:"פליפינג",en:"Flipping / Position Flipping",category:"prop",definition:"מעבר מהיר מפוזיציית לונג לפוזיציית שורט, או להפך, באותו מכשיר פיננסי. חלק מחברות המימון עשויות להגביל דפוסי פליפינג מסוימים, במיוחד כאשר הם משמשים לעקיפת כללי מסחר או לניצול תנאי ביצוע."},{id:"account-breach",he:"פסילת חשבון",en:"Breach / Account Violation",category:"prop",definition:"סגירת החשבון על ידי חברת המימון אחרי הפרה של כלל מחייב, למשל נגיעה בדרודאון או חריגה מהגבלת ההפסד היומית. ברוב המקרים החשבון אבוד, וכדי להמשיך צריך לקנות חשבון חדש או לעשות ריסט.",related:["maximum-drawdown-maximum-loss-limit","daily-loss-limit","account-reset"]},{id:"new-day-opening-gap",he:"פער פתיחת יום",en:"New Day Opening Gap - NDOG",category:"ict",definition:"מושג בשיטת ICT המתאר פער בין מחיר הסגירה של יום מסחר קודם למחיר הפתיחה של יום המסחר הבא, לפי הגדרת יום המסחר במודל. משמש לזיהוי רמות מחיר שעשויות להשפיע על התנהגות השוק במהלך היום.",related:["new-week-opening-gap"]},{id:"new-week-opening-gap",he:"פער פתיחת שבוע",en:"New Week Opening Gap - NWOG",category:"ict",definition:"מושג בשיטת ICT המתאר את הפער בין מחיר הסגירה של שבוע המסחר הקודם למחיר הפתיחה של השבוע החדש, בהתאם להגדרת שעות המסחר. סוחרים עשויים להשתמש בגבולות הפער כרמות ייחוס לניתוח תנועת המחיר במהלך השבוע.",related:["new-day-opening-gap"]},{id:"iceberg-order",he:"פקודת אייסברג",en:"Iceberg Order",category:"fundamentals",definition:"פקודת מסחר שבה רק חלק מהכמות הכוללת גלוי בספר הפקודות, בעוד יתרת הכמות מוסתרת או נחשפת בהדרגה. בניתוח Order Flow סוחרים מנסים לזהות פעילות כזו באמצעות שילוב של נתוני ביצוע ועומק שוק."},{id:"limit-order",he:"פקודת לימיט",en:"Limit Order",category:"fundamentals",definition:"פקודה לקנייה או למכירה במחיר מוגדר או במחיר טוב ממנו. מאפשרת שליטה במחיר הביצוע, אך אינה מבטיחה שהעסקה תתבצע.",related:["market-order","stop-market-order","stop-limit-order"],links:[{type:"video",id:"trading-orders"}]},{id:"market-order",he:"פקודת מרקט",en:"Market Order",category:"fundamentals",definition:"פקודה לקנייה או למכירה המתבצעת מול הנזילות הזמינה בשוק. מעניקה עדיפות למהירות הביצוע, אך אינה מבטיחה מחיר ביצוע מסוים.",related:["limit-order","stop-market-order","stop-limit-order"],links:[{type:"video",id:"trading-orders"}]},{id:"contract-expiration",he:"פקיעת חוזה",en:"Contract Expiration",category:"futures",definition:"המועד שבו מסתיימת תקופת המסחר או חלות התחייבויות הסילוק של חוזה עתידי, בהתאם למפרט החוזה. סוחרים נדרשים להכיר את מועד הפקיעה ואת כללי הברוקר כדי להימנע מהחזקה לא מתוכננת לקראת הסילוק.",related:["contract-rollover","continuous-futures-contract"],links:[{type:"video",id:"contract-rollover"}]},{id:"projectx",he:"פרוג'קט X",en:"ProjectX",category:"platforms",definition:"פלטפורמת מסחר שחברות מימון בחוזים עתידיים משתמשות בה לחשבונות של הסוחרים. יש חברות שמציעות אותה במקום Tradovate או Rithmic, ולפעמים תחת שם משלהן, כמו TopstepX.",related:["topstepx","tradovate","rithmic"]},{id:"proprietary-trading-firm",he:"פרופ פירם",en:"Proprietary Trading Firm - Prop Firm",category:"prop",definition:"חברה העוסקת במסחר באמצעות הון החברה או מפעילה תוכניות המאפשרות לסוחרים לקבל תגמול על ביצועיהם בהתאם לתנאים מוגדרים. בענף חברות המימון לסוחרים, תוכניות רבות מבוססות על חשבונות סימולציה ולא בהכרח על מסחר בהון אמיתי.",links:[{type:"route",to:"/comparison",label:"השוואת חברות מימון"},{type:"route",to:"/matching-quiz",label:"מבחן התאמה לחברת מימון"},{type:"route",to:"/nostro-course",label:"קורס הנוסטרו החינמי"}]},{id:"profit-split",he:"פרופיט ספליט",en:"Profit Split",category:"prop",definition:"הסדר חלוקת הרווחים בין הסוחר לחברת המימון בהתאם לתנאי התוכנית. שיעור הרווח המגיע לסוחר עשוי להשתנות בין חברות, מסלולים ושלבי החשבון.",related:["payout","payout-cap","payout-waiting-period","payout-bonus"]},{id:"price-action",he:"פרייס אקשן",en:"Price Action",category:"technical",definition:"שיטת ניתוח המתמקדת בהתנהגות המחיר עצמו, באמצעות נרות, שיאים ושפלים, מבנה שוק ורמות מחיר. מאפשרת לבחון את השוק ללא תלות הכרחית באינדיקטורים."},{id:"breakout",he:"פריצה",en:"Breakout",category:"technical",definition:"תנועת מחיר שחוצה רמת תמיכה, התנגדות או גבול של טווח מסחר. סוחרים בוחנים את עוצמת הפריצה, נפח המסחר והתנהגות המחיר לאחריה כדי להעריך אפשרות להמשך התנועה.",related:["false-breakout"]},{id:"false-breakout",he:"פריצת שווא",en:"False Breakout",category:"technical",definition:"מצב שבו המחיר חוצה רמת מחיר משמעותית אך אינו מצליח להמשיך בכיוון הפריצה וחוזר אל תוך הטווח הקודם. עשוי להוביל ללכידת סוחרים שנכנסו בעקבות הפריצה.",related:["breakout"]},{id:"liquidity-buildup",he:"צבירת נזילות",en:"Liquidity Buildup",category:"ict",definition:"מצב שבו מתפתח ריכוז צפוי של פקודות סביב רמות מחיר מסוימות, למשל מעל שיאים חוזרים או מתחת לשפלים חוזרים. בשיטות ICT/SMC סוחרים עשויים לעקוב אחר אזורים אלה כיעדים אפשריים לתנועת המחיר."},{id:"interest-rate-expectations",he:"ציפיות ריבית",en:"Interest Rate Expectations",category:"macro",definition:"הערכות המשתתפים בשוק לגבי החלטות הריבית העתידיות של הבנק המרכזי. שינויים בציפיות אלה עשויים להשפיע על חוזים עתידיים של מדדי מניות, איגרות חוב ומטבעות, במיוחד סביב פרסומים כלכליים.",related:["federal-reserve","federal-funds-rate"]},{id:"pre-market-trading",he:"קדם-מסחר",en:"Pre-Market Trading",category:"fundamentals",definition:"פעילות מסחר המתקיימת לפני פתיחת שעות המסחר הרגילות של שוק המניות. סוחרי חוזים עתידיים עשויים לבחון את תנועות המחיר בתקופה זו לצורך זיהוי רמות משמעותיות והיערכות לפתיחת השוק."},{id:"trendline",he:"קו מגמה",en:"Trendline",category:"technical",definition:"קו המשורטט על גבי הגרף באמצעות חיבור נקודות שיא או שפל משמעותיות. משמש לזיהוי כיוון המגמה, לבחינת תגובות מחיר ולזיהוי שבירה אפשרית של המבנה הקיים."},{id:"discount-code",he:"קוד הנחה",en:"Discount Code / Affiliate Code",category:"prop",definition:"קוד שמזינים בקנייה של חשבון ומקבלים עליו הנחה. בחלק מהחברות ההנחה חלה רק על החודש הראשון ולא על החידושים, ולכן כדאי לבדוק את זה לפני הקנייה. אצלנו הקוד ברוב החברות הוא ANTAR, ואת הקוד המעודכן לכל חברה אפשר למצוא בעמוד המבצעים.",related:["account-renewal"],links:[{type:"route",to:"/promotions",label:"מבצעים וקודי הנחה"}]},{id:"consolidation",he:"קונסולידציה",en:"Consolidation",category:"technical",definition:"מצב שבו המחיר נע בתוך טווח מוגדר יחסית, ללא מגמת עלייה או ירידה ברורה. סוחרים עוקבים אחר גבולות הטווח כדי לזהות פריצה אפשרית, הצטברות נזילות או המשך של המגמה הקודמת.",links:[{type:"video",id:"consolidation"}]},{id:"copy-trading",he:"קופי טריידינג",en:"Copy Trading",category:"prop",definition:"שיטה שבה עסקאות המבוצעות בחשבון אחד מועתקות באופן אוטומטי לחשבונות נוספים באמצעות תוכנה או שירות מתאים. חברות מימון עשויות להגביל את השימוש בהעתקת עסקאות בהתאם לכללי החשבונות והבעלות עליהם.",links:[{type:"route",to:"/replikanto-guide",label:"מדריך Replikanto"},{type:"route",to:"/tradesyncer-guide",label:"מדריך TradeSyncer"}]},{id:"correlation",he:"קורלציה",en:"Correlation",category:"technical",definition:"מדד המתאר את הקשר בין תנועות המחירים של שני נכסים פיננסיים. לדוגמה, חוזי NQ ו־ES נוטים לעיתים לנוע בכיוונים דומים, אך הקורלציה ביניהם אינה קבועה ועשויה להשתנות.",links:[{type:"video",id:"es-nq-correlation"}]},{id:"kill-zone",he:"קילזון",en:"Kill Zone",category:"ict",definition:"חלון זמן מוגדר בשיטת ICT שבו סוחרים מחפשים הזדמנויות מסחר בהתאם להתנהגות המחיר והנזילות. קיימים חלונות זמן המזוהים עם סשנים שונים, כגון לונדון וניו יורק, אך עצם הכניסה לחלון אינה מבטיחה הזדמנות מסחר."},{id:"aggressive-buying",he:"קנייה אגרסיבית",en:"Aggressive Buying",category:"orderflow",definition:"ביצוע פקודות קנייה מול פקודות מכירה ממתינות בצד ה־Ask. בניתוח Order Flow, קנייה אגרסיבית עשויה להצביע על לחץ מצד קונים, אך אינה מבטיחה שהמחיר ימשיך לעלות.",related:["aggressive-selling","passive-buying","absorption"]},{id:"passive-buying",he:"קנייה פסיבית",en:"Passive Buying",category:"orderflow",definition:"הצבת פקודות קנייה ממתינות, בדרך כלל באמצעות פקודות Limit, המספקות נזילות לספר הפקודות. פקודות אלה עשויות לספוג מכירות אגרסיביות כאשר הן מבוצעות.",related:["aggressive-buying","aggressive-selling","absorption"]},{id:"capitulation",he:"קפיטולציה",en:"Capitulation",category:"orderflow",definition:"מצב שבו משתתפים רבים בשוק סוגרים פוזיציות בעקבות לחץ משמעותי, לעיתים תוך תנועת מחיר חדה ונפח מסחר גבוה. עשוי להופיע לקראת סיום מהלך משמעותי, אך אינו מבטיח היפוך מגמה."},{id:"gross-profit",he:"רווח גולמי",en:"Gross Profit",category:"performance",definition:"סך הרווחים שהתקבלו מעסקאות רווחיות בתקופה מסוימת, לפני קיזוז הפסדים ועלויות מסחר. משמש בין היתר לחישוב יחס הרווחיות (Profit Factor).",related:["net-profit"]},{id:"profit-and-loss",he:"רווח והפסד",en:"Profit and Loss - P&L",category:"performance",definition:"המדד המציג את התוצאה הכספית של פעילות המסחר. נהוג להבחין בין רווח והפסד ממומשים מעסקאות שנסגרו לבין רווח והפסד שטרם מומשו מפוזיציות פתוחות."},{id:"unrealized-profit",he:"רווח לא ממומש",en:"Unrealized Profit",category:"performance",definition:"רווח שקיים בפוזיציה פתוחה אך טרם מומש באמצעות סגירתה. גובה הרווח משתנה בהתאם לתנועות המחיר בשוק, והוא עשוי להצטמצם או להיעלם לפני סגירת העסקה.",related:["realized-profit"]},{id:"realized-profit",he:"רווח ממומש",en:"Realized Profit",category:"performance",definition:"רווח שהתקבל בעקבות סגירת פוזיציה רווחית, במלואה או בחלקה. הרווח הממומש אינו משתנה עוד בעקבות תנועת המחיר של אותה כמות שנסגרה.",related:["unrealized-profit"]},{id:"average-trade-profit",he:"רווח ממוצע לעסקה",en:"Average Trade Profit",category:"performance",definition:"הרווח או ההפסד הממוצע לעסקה, המחושב באמצעות חלוקת התוצאה הכספית הכוללת במספר העסקאות. משמש להערכת הביצועים הממוצעים של אסטרטגיית מסחר לאורך זמן.",links:[{type:"article",slug:"journal-statistics-1-to-1"}]},{id:"net-profit",he:"רווח נקי",en:"Net Profit",category:"performance",definition:"הרווח שנותר מפעילות המסחר לאחר הפחתת הפסדים ועלויות רלוונטיות, כגון עמלות מסחר. משמש להערכת התוצאה הכספית בפועל של הסוחר לאורך תקופה מוגדרת.",related:["gross-profit"]},{id:"federal-funds-rate",he:"ריבית הפד",en:"Federal Funds Rate",category:"macro",definition:"ריבית היעד שקובע הבנק המרכזי של ארצות הברית עבור שוק ההלוואות הבין־בנקאיות לטווח קצר. החלטות הריבית והציפיות לשינויים בה עשויות להשפיע על מדדי המניות, איגרות החוב והחוזים העתידיים.",related:["federal-reserve","interest-rate-expectations"]},{id:"retest",he:"ריטסט",en:"Retest",category:"technical",definition:"חזרה של המחיר לרמה שנפרצה או לאזור טכני משמעותי לאחר תנועה קודמת. סוחרים בוחנים את תגובת המחיר בריטסט כדי לזהות אישור אפשרי להמשך התנועה או כישלון הפריצה."},{id:"rise",he:"רייז",en:"Rise",category:"platforms",definition:"פלטפורמת תשלומים שחלק מחברות המימון משתמשות בה כדי להעביר משיכות לסוחרים מחוץ לארצות הברית. פותחים בה חשבון, עוברים אימות זהות, ומשם מעבירים את הכסף לבנק.",related:["payout","identity-verification","wire-transfer"]},{id:"account-reset",he:"ריסט/איפוס חשבון",en:"Account Reset",category:"prop",definition:"תשלום שמחזיר את חשבון ההערכה ליתרת הפתיחה כדי להתחיל את המבחן מחדש. לרוב זול יותר מחשבון חדש, אבל המחיר והתנאים, למשל אם גם ימי המסחר מתאפסים, משתנים בין החברות.",related:["account-breach","evaluation-account","account-renewal"]},{id:"risk-free-trade",he:"ריסק-פרי טרייד",en:"Risk-Free Trade",category:"risk",definition:"כינוי מקובל בקרב סוחרים לעסקה שבה הסיכון הראשוני צומצם באופן משמעותי, לרוב באמצעות הזזת הסטופ למחיר הכניסה לאחר שהמחיר התקדם בכיוון הרצוי. למרות הכינוי, העסקה אינה בהכרח נטולת סיכון לחלוטין, בשל עמלות, סליפג׳ והפרשי ביצוע אפשריים."},{id:"rithmic",he:"ריתמיק",en:"Rithmic",category:"platforms",definition:"ספקית תשתיות מסחר ונתוני שוק, המשמשת בין היתר סוחרים בחוזים עתידיים וחברות מימון. השירותים שלה מאפשרים חיבור למערכות ביצוע ולפלטפורמות תואמות, בכפוף להרשאות ולתנאי החשבון."},{id:"previous-month-high-low",he:"רמות חודש קודם",en:"PMH / PML – Previous Month High / Low",category:"ict",definition:"רמות השיא והשפל שנקבעו במהלך חודש המסחר הקודם. משמשות בניתוח רב־תקופתי לזיהוי אזורי נזילות ורמות מחיר בעלות חשיבות אפשרית בטווח רחב יותר."},{id:"previous-day-high-low",he:"רמות יום קודם",en:"PDH / PDL – Previous Day High / Low",category:"ict",definition:"רמות השיא והשפל שנקבעו ביום המסחר הקודם, בהתאם להגדרת יום המסחר שבה משתמשים. בשיטות ICT/SMC הן משמשות כרמות ייחוס מרכזיות וכאזורים שבהם עשויה להימצא נזילות."},{id:"previous-week-high-low",he:"רמות שבוע קודם",en:"PWH / PWL – Previous Week High / Low",category:"ict",definition:"רמות השיא והשפל של שבוע המסחר הקודם. סוחרים עוקבים אחריהן לצורך זיהוי מבנה השוק הרחב, יעדי מחיר אפשריים ואזורי נזילות משמעותיים."},{id:"replikanto",he:"רפליקנטו",en:"Replikanto",category:"platforms",definition:"תוסף להעתקת עסקאות בין חשבונות מסחר בסביבת NinjaTrader. הוא מאפשר להגדיר חשבון מוביל וחשבונות עוקבים, כך שפקודות מסוימות יועתקו ביניהם לפי ההגדרות שנבחרו."},{id:"losing-streak",he:"רצף הפסדים",en:"Losing Streak",category:"performance",definition:"סדרה של עסקאות מפסידות המתרחשות ברציפות. משמשת לניתוח ביצועי אסטרטגיה, הערכת תקופות של ירידה בהון והתאמת כללי ניהול הסיכונים.",related:["winning-streak"]},{id:"stacked-imbalance",he:"רצף חוסרי איזון",en:"Stacked Imbalance",category:"orderflow",definition:"רצף של רמות מחיר סמוכות בגרף Footprint שבהן מזוהים חוסרי איזון באותו כיוון, בהתאם לסף שהוגדר. סוחרים משתמשים בו לזיהוי פעילות קנייה או מכירה אגרסיבית במספר רמות מחיר.",related:["footprint-chart","imbalance"],links:[{type:"video",id:"imbalances"},{type:"article",slug:"footprint-guide"}]},{id:"winning-streak",he:"רצף רווחים",en:"Winning Streak",category:"performance",definition:"סדרה של עסקאות רווחיות המתרחשות ברציפות. למרות שרצף כזה עשוי לשפר את ביצועי החשבון, הוא אינו מבטיח הצלחה בעסקאות הבאות.",related:["losing-streak"]},{id:"break-of-structure",he:"שבירת מבנה",en:"Break of Structure - BOS",category:"ict",definition:"מצב שבו המחיר פורץ שיא או שפל מבני משמעותי בכיוון המגמה הקיימת. בשיטות ICT/SMC שבירת מבנה משמשת לרוב כאישור אפשרי להמשך המגמה, בהתאם לאופן שבו הוגדר המבנה.",related:["change-of-character","market-structure-shift","change-in-state-of-delivery"]},{id:"bear-market",he:"שוק דובי",en:"Bear Market",category:"technical",definition:"מצב שוק המתאפיין במגמת ירידה רחבה ומתמשכת, בדרך כלל לצד סנטימנט שלילי מצד המשקיעים. עשוי לכלול גם עליות ותיקונים זמניים במהלך המגמה היורדת."},{id:"open-market",he:"שוק פתוח",en:"Open Market",category:"fundamentals",definition:"מצב שבו זירת המסחר פעילה ומאפשרת ביצוע עסקאות בהתאם לשעות הפעילות ולכללי הבורסה. בחוזים עתידיים יש להבחין בין פעילות המסחר האלקטרוני לבין שעות המסחר הרגילות של שוק נכס הבסיס."},{id:"bull-market",he:"שוק שורי",en:"Bull Market",category:"technical",definition:"מצב שוק המתאפיין במגמת עלייה רחבה ומתמשכת, בדרך כלל לצד ציפיות חיוביות מצד המשקיעים. המונח מתאר מגמה כללית ואינו מחייב שכל יום מסחר יסתיים בעליות."},{id:"higher-high",he:"שיא גבוה יותר",en:"Higher High - HH",category:"technical",definition:"מצב שבו המחיר יוצר שיא חדש הגבוה מהשיא המבני הקודם. רצף של שיאים גבוהים יותר, לצד שפלים עולים, מאפיין בדרך כלל מגמת עלייה.",related:["lower-high","higher-low","lower-low"]},{id:"all-time-high",he:"שיא כל הזמנים",en:"All-Time High - ATH",category:"technical",definition:"רמת המחיר הגבוהה ביותר שנרשמה לנכס לאורך ההיסטוריה הנמדדת שלו. בחוזים עתידיים יש להבחין בין שיא של חוזה מסוים לבין שיא של מדד הבסיס או סדרת חוזים רציפה."},{id:"lower-high",he:"שיא נמוך יותר",en:"Lower High - LH",category:"technical",definition:"מצב שבו המחיר יוצר שיא הנמוך מהשיא המבני הקודם. רצף של שיאים יורדים, לצד שפלים יורדים, מאפיין בדרך כלל מגמת ירידה.",related:["higher-high","higher-low","lower-low"]},{id:"equal-highs",he:"שיאים שווים",en:"Equal Highs - EQH",category:"technical",definition:"שני שיאים או יותר הנמצאים ברמות מחיר קרובות מאוד. בשיטות ICT/SMC הם נחשבים לאזור שבו עשויה להצטבר נזילות קנייה, בין היתר בעקבות פקודות סטופ של סוחרי שורט.",related:["equal-lows"]},{id:"change-of-character",he:"שינוי אופי",en:"Change of Character - CHOCH",category:"ict",definition:"שינוי בהתנהגות מבנה המחיר, המתבטא לרוב בשבירת נקודת מבנה נגד כיוון המגמה הקודמת. בשיטות ICT/SMC הוא עשוי להצביע על תחילתו של שינוי כיוון, אך אינו מבטיח היפוך מגמה.",related:["break-of-structure","market-structure-shift","change-in-state-of-delivery"]},{id:"change-in-state-of-delivery",he:"שינוי במצב המסירה",en:"Change in State of Delivery - CISD",category:"ict",definition:"מושג בשיטת ICT המתאר שינוי באופן שבו המחיר נע ומוסר את התנועה לשוק, לעיתים באמצעות שבירת רמת פתיחה של נרות משמעותיים במהלך קודם. משמש לזיהוי מעבר אפשרי משליטת קונים לשליטת מוכרים או להפך, בהתאם להגדרת המודל.",related:["break-of-structure","change-of-character","market-structure-shift"]},{id:"market-structure-shift",he:"שינוי מבנה שוק",en:"Market Structure Shift - MSS",category:"ict",definition:"מושג בשיטת ICT המתאר שינוי משמעותי במבנה המחיר, לרוב בעקבות שבירת שיא או שפל מבני נגד כיוון התנועה הקודמת. השינוי עשוי להיות מלווה בתנועת מחיר חזקה (Displacement), ומשמש לזיהוי מעבר אפשרי בשליטת הקונים והמוכרים.",related:["break-of-structure","change-of-character","change-in-state-of-delivery"]},{id:"distribution-phase",he:"שלב הפצה",en:"Distribution Phase",category:"technical",definition:"שלב במודל ווייקוף שבו עשויה להתרחש מכירה הדרגתית של נכס לאחר עלייה משמעותית או בתקופת דשדוש. סוחרים בוחנים את מבנה המחיר והנפח כדי לזהות סימנים אפשריים להיחלשות הביקוש."},{id:"eastern-time",he:"שעון ניו יורק",en:"Eastern Time - ET",category:"futures",definition:"אזור הזמן שלפיו נקבעים שעות המסחר, פרסום הנתונים והכללים של רוב חברות המימון, למשל שעת הסגירה החובה. ישראל בדרך כלל 7 שעות לפני ניו יורק, ובשבועות של המעבר לשעון קיץ או חורף ההפרש הוא 6 שעות.",related:["new-york-session","trading-session"]},{id:"extended-trading-hours",he:"שעות מסחר מורחבות",en:"Extended Trading Hours - ETH",category:"fundamentals",definition:"שעות המסחר המתקיימות מחוץ לשעות הפעילות הרגילות של שוק נכס הבסיס. בחוזים עתידיים על מדדי מניות אמריקאיים המסחר מתקיים במשך חלק גדול מהיממה, בכפוף להפסקות וללוח הזמנים של הבורסה."},{id:"closing-price",he:"שער סגירה",en:"Closing Price",category:"fundamentals",definition:"המחיר האחרון שנרשם בתקופת מסחר מוגדרת, בהתאם למקור הנתונים ולהגדרת התקופה. משמש לניתוח נרות, חישוב אינדיקטורים והשוואת ביצועי המחיר בין תקופות."},{id:"opening-price",he:"שער פתיחה",en:"Opening Price",category:"fundamentals",definition:"המחיר הראשון שבו בוצעה עסקה בתחילת תקופת מסחר מוגדרת. סוחרים עשויים להשתמש בשער הפתיחה של יום, סשן או נר כרמת ייחוס לניתוח התנהגות המחיר."},{id:"higher-low",he:"שפל גבוה יותר",en:"Higher Low - HL",category:"technical",definition:"מצב שבו המחיר יוצר שפל חדש הגבוה מהשפל המבני הקודם. משמש לזיהוי המשכיות אפשרית של מגמת עלייה ולבחינת חוזק מבנה השוק.",related:["higher-high","lower-high","lower-low"]},{id:"all-time-low",he:"שפל כל הזמנים",en:"All-Time Low - ATL",category:"technical",definition:"רמת המחיר הנמוכה ביותר שנרשמה לנכס לאורך ההיסטוריה הנמדדת שלו. בחוזים עתידיים משמעות הרמה תלויה בחוזה, בתקופת המדידה ובאופן חיבור הנתונים ההיסטוריים."},{id:"lower-low",he:"שפל נמוך יותר",en:"Lower Low - LL",category:"technical",definition:"מצב שבו המחיר יוצר שפל חדש הנמוך מהשפל המבני הקודם. משמש לזיהוי המשכיות אפשרית של מגמת ירידה ולבחינת לחץ המכירה בשוק.",related:["higher-high","lower-high","higher-low"]},{id:"equal-lows",he:"שפלים שווים",en:"Equal Lows - EQL",category:"technical",definition:"שני שפלים או יותר הנמצאים ברמות מחיר קרובות מאוד. בשיטות ICT/SMC הם נחשבים לאזור שבו עשויה להצטבר נזילות מכירה, בין היתר בעקבות פקודות סטופ של סוחרי לונג.",related:["equal-highs"]},{id:"double-bottom",he:"תבנית דאבל בוטום",en:"Double Bottom",category:"technical",definition:"תבנית שבה המחיר יוצר שני שפלים ברמות דומות, עם עלייה ביניהם. עשויה להצביע על היחלשות מגמת ירידה, כאשר פריצת השיא שבין השפלים משמשת לעיתים כאישור לתבנית.",related:["double-top"]},{id:"double-top",he:"תבנית דאבל טופ",en:"Double Top",category:"technical",definition:"תבנית שבה המחיר יוצר שני שיאים ברמות דומות, עם ירידה ביניהם. עשויה להצביע על היחלשות מגמת עלייה, כאשר שבירת השפל שבין השיאים משמשת לעיתים כאישור לתבנית.",related:["double-bottom"]},{id:"flag-pattern",he:"תבנית דגל",en:"Flag Pattern",category:"technical",definition:"תבנית המשכיות שבה המחיר מבצע תנועה חדה ולאחריה מתכנס לתיקון קצר יחסית. סוחרים עוקבים אחר פריצה של התבנית בכיוון המהלך המקורי, אך המשך המגמה אינו מובטח."},{id:"head-and-shoulders",he:"תבנית ראש וכתפיים",en:"Head and Shoulders",category:"technical",definition:"תבנית ניתוח טכני המורכבת משלושה שיאים, כאשר השיא האמצעי גבוה משני השיאים הסמוכים. משמשת לזיהוי היפוך אפשרי ממגמת עלייה לירידה, במיוחד לאחר שבירת קו הצוואר.",related:["inverse-head-and-shoulders"]},{id:"inverse-head-and-shoulders",he:"תבנית ראש וכתפיים הפוכה",en:"Inverse Head and Shoulders",category:"technical",definition:"תבנית המורכבת משלושה שפלים, כאשר השפל האמצעי נמוך משני השפלים הסמוכים. עשויה להצביע על מעבר אפשרי ממגמת ירידה לעלייה לאחר פריצת קו הצוואר.",related:["head-and-shoulders"]},{id:"trading-frequency",he:"תדירות מסחר",en:"Trading Frequency",category:"performance",definition:"מספר העסקאות המבוצעות בפרק זמן מוגדר. משמש לניתוח דפוסי המסחר, התאמת האסטרטגיה ובחינת חריגה אפשרית מתוכנית המסחר."},{id:"trading-expectancy",he:"תוחלת מסחר",en:"Trading Expectancy",category:"performance",definition:"הרווח או ההפסד הממוצע הצפוי לעסקה על בסיס שיעור העסקאות המנצחות, שיעור העסקאות המפסידות וגודל הרווח וההפסד הממוצעים. תוחלת חיובית עשויה להצביע על יתרון סטטיסטי, אך אינה מבטיחה רווחיות בעתיד.",related:["win-rate","risk-reward-ratio","profit-factor"],links:[{type:"article",slug:"journal-statistics-1-to-1"}]},{id:"scaling-plan",he:"תוכנית הגדלת חשבון",en:"Scaling Plan",category:"prop",definition:"מערכת כללים המאפשרת להגדיל בהדרגה את היקף המסחר המותר או את הקצאת ההון בהתאם לתנאים מוגדרים. בחברות מימון התוכנית עשויה להתבסס על ביצועים, יתרת חשבון או שלב המימון."},{id:"trading-plan",he:"תוכנית מסחר",en:"Trading Plan",category:"performance",definition:"תוכנית מסחר המגדירה את תנאי הכניסה והיציאה מעסקאות, ניהול הסיכונים ושעות הפעילות של הסוחר. מטרתה ליצור תהליך עבודה עקבי ומוגדר מראש, במקום קבלת החלטות מאולתרת במהלך המסחר."},{id:"mark-to-market",he:"תמחור לפי שוק",en:"Mark-to-Market",category:"fundamentals",definition:"תהליך שבו שווי פוזיציה או חשבון מתעדכן בהתאם למחירי השוק. בחוזים עתידיים מתבצעת גם התחשבנות יומית על רווחים והפסדים בהתאם לכללי הבורסה והסליקה."},{id:"support",he:"תמיכה",en:"Support",category:"technical",definition:"רמת מחיר או אזור שבו הופיע בעבר ביקוש שהאט או עצר ירידה. סוחרים בוחנים את תגובת המחיר כאשר הוא חוזר לאזור, אך אין ודאות שהתמיכה תחזיק שוב.",related:["resistance"]},{id:"volatility",he:"תנודתיות",en:"Volatility",category:"technical",definition:"מידת השינוי במחיר של נכס פיננסי לאורך תקופה מסוימת. תנודתיות גבוהה מתאפיינת בדרך כלל בתנועות מחיר רחבות יותר, ועשויה להשפיע על גודל הסטופ, הסיכון ועלויות הביצוע."},{id:"payout-waiting-period",he:"תקופת המתנה למשיכה",en:"Payout Waiting Period",category:"prop",definition:"פרק הזמן הנדרש בין אירועים הקשורים למשיכות, כגון פתיחת חשבון, בקשת משיכה קודמת או מועד זכאות חדש. התנאים משתנים בין חברות המימון והמסלולים.",related:["payout","payout-cap","payout-bonus","profit-split"]},{id:"payout-cap",he:"תקרת משיכה",en:"Payout Cap",category:"prop",definition:"הסכום המרבי שסוחר רשאי למשוך במסגרת בקשת משיכה או תקופה מוגדרת, בהתאם לכללי חברת המימון. התקרה עשויה להשתנות בין מסלולים, שלבי חשבון וסוגי משיכות.",related:["payout","payout-waiting-period","payout-bonus","profit-split"]},{id:"activation-fee",he:"תשלום הפעלה",en:"Activation Fee",category:"prop",definition:"תשלום שחלק מחברות המימון גובות לאחר מעבר שלב ההערכה ולפני הפעלת חשבון ההמשך. קיומו, גובהו ותנאי התשלום תלויים במסלול ובמדיניות החברה."},{id:"payout",he:"תשלום משיכה",en:"Payout",category:"prop",definition:"תשלום רווחים לסוחר בהתאם לתנאים שנקבעו בתוכנית חברת המימון. הזכאות לתשלום עשויה להיות כפופה לכללי עקביות, מגבלות הפסד, תנאי חשבון ובדיקות נוספות.",related:["payout-cap","payout-waiting-period","payout-bonus","profit-split"],links:[{type:"route",to:"/calculators/payout-odds",label:"מחשבון סיכויי משיכה"}]}],e="את הערך המדויק בכל חברה ומסלול אפשר לראות בהשוואת החברות ובעמוד של כל חברה, בלשונית החוקים.",t=[{id:"consistency-rule",seoTitle:"חוק עקביות (Consistency Rule) בחברות מימון: מה זה ואיך מחשבים",seoDescription:"מה זה חוק העקביות בחברות מימון ונוסטרו, למה הוא קיים, איך מחשבים כמה רווח צריך לפני משיכה (היום הגדול חלקי אחוז העקביות) ואיך לא להיפסל בגללו.",lead:"חוק עקביות קובע שיום רווחי אחד לא יהיה יותר מאחוז מסוים מסך הרווחים בחשבון. המטרה: לוודא שהגעתם ליעד בזכות מסחר עקבי, ולא בזכות יום אחד של מזל.",sections:[{title:"למה חברות המימון מוסיפות חוק עקביות",body:["בלי החוק הזה, אפשר היה להיכנס עם כמות גדולה, להרוויח הרבה ביום אחד ולבקש משיכה. אם זה לא הולך, מפסידים רק את מחיר המבחן. החברות לא רוצות לשלם על הימור. הן רוצות לראות סוחר שיודע להרוויח שוב ושוב: 400, 500, 600 דולר, ולא 3,000 ביום אחד ואז כלום."]},{title:"איך מחשבים",body:["הנוסחה פשוטה: היום הכי רווחי שלכם, חלקי אחוז העקביות, שווה סך הרווח שצריך כדי לבקש משיכה.","לדוגמה: היום הכי גדול שלכם היה 1,200 דולר, והחוק הוא 30%. 1,200 ÷ 0.3 = 4,000 דולר. כלומר, צריך להגיע לרווח כולל של 4,000 דולר לפני שמבקשים משיכה. בחוק של 50% אותו יום מחייב רק 2,400 דולר.","בדרך כלל החוק נבדק רק כשמבקשים משיכה, או כשעוברים מבחן. לכן יום גדול לא פוסל את החשבון, הוא רק מרחיק את היעד."]},{title:"איך עובדים עם החוק",body:["• הציבו יעד יומי קבוע ומתון, ותנו לזמן לעבוד.","• היה לכם יום חריג? חשבו מיד את היעד החדש, כדי לדעת כמה עוד צריך.","• האחוז משתנה בין החברות, ויש מסלולים בלי חוק עקביות בכלל. "+e]}],video:{id:"efHZNdtoOCc",title:"מה זה חוק עקביות?"},image:{src:"/blog/tik-nostro/l3-consistency-rule.jpg",alt:"חוק העקביות: מה זה, למה הוא קיים ודוגמה מספרית"},faq:[{q:"מתי נבדק חוק העקביות?",a:"ברוב החברות כשמבקשים משיכה או כשמסיימים מבחן. עד אז אפשר להרוויח כמה שרוצים ביום, אבל יום גדול מגדיל את סך הרווח שצריך."},{q:"מה קורה אם עברתי את אחוז העקביות?",a:"בדרך כלל החשבון לא נפסל. פשוט צריך להמשיך לסחור עד שהיום הגדול יהיה פחות מהאחוז המותר מסך הרווחים."},{q:"יש חברות בלי חוק עקביות?",a:"כן, יש מסלולים בלי חוק עקביות, בעיקר בחשבונות הממומנים. אפשר לסנן אותם בהשוואת החברות."}],articles:["tik-nostro","how-to-pass-prop-firm-evaluation"]},{id:"trailing-drawdown",seoTitle:"טריילינג דראודאון (Trailing Drawdown): מה זה הסטופ הנגרר בחברות מימון",seoDescription:"מה זה Trailing Drawdown בחברות מימון: איך הסטופ עולה יחד עם הרווח, ההבדל בין טריילינג תוך-יומי לסוף יום, מתי הוא ננעל ואיך לא לשרוף חשבון בגללו.",lead:"טריילינג דראודאון הוא סטופ שעולה יחד עם הרווח שלכם. הרווחתם 1,000 דולר? הסטופ עלה ב-1,000 דולר. הוא אף פעם לא יורד בחזרה, ולכן חשבון יכול להישרף גם כשהוא עדיין ברווח.",sections:[{title:"דוגמה בחשבון של 50,000",body:["נניח סטופ של 2,000 דולר. בהתחלה הסטופ על 48,000. הגעתם ל-51,000? הסטופ עלה ל-49,000. הגעתם ל-52,000? הסטופ על 50,000. מעכשיו, ירידה ל-50,000 שורפת את החשבון, למרות שזה בדיוק הסכום שבו התחלתם."]},{title:"שני סוגים",body:["• טריילינג תוך-יומי: הסטופ זז בזמן אמת, גם לפי רווח פתוח בתוך עסקה שעוד לא נסגרה.","• טריילינג סוף יום (EOD): הסטופ מתעדכן רק לפי היתרה שבה סגרתם את היום. מה שקרה באמצע היום לא מזיז אותו, ולכן לרוב הוא נוח יותר למתחילים."]},{title:"מתי הסטופ ננעל",body:["ברוב החשבונות הממומנים הסטופ מפסיק לעלות בנקודה מסוימת, למשל כשהוא מגיע לגובה החשבון ההתחלתי. מאותו רגע אפשר להמשיך להרוויח בלי שהסטופ ירדוף אחריכם. "+e]}],image:{src:"/blog/tik-nostro/l3-trailing-intraday-vs-eod.jpg",alt:"טריילינג תוך-יומי מול טריילינג סוף יום: דוגמה בחשבון 50K"},faq:[{q:"למה החשבון נשרף כשהייתי ברווח?",a:"כי הסטופ עלה יחד עם השיא שהגעתם אליו. אם הייתם ברווח של 2,000 וירדתם 2,000 מהשיא, החשבון נשרף, גם אם אתם עדיין מעל הסכום ההתחלתי."},{q:"מה עדיף, תוך-יומי או סוף יום?",a:"למתחילים בדרך כלל סוף יום, כי תנודות באמצע היום לא מזיזות את הסטופ. תוך-יומי דורש יציאה מדויקת יותר מעסקאות."},{q:"איך רואים איפה הסטופ שלי?",a:"בפלטפורמה של החשבון. במדריך לטריידובייט באתר מוסבר בדיוק איפה רואים את נקודת ה-Drawdown."}],articles:["tradovate-drawdown","tik-nostro"]},{id:"intraday-trailing-drawdown",seoTitle:"סטופ תוך-יומי (Intraday Trailing Drawdown): איך הוא עובד ולמה הוא מסוכן",seoDescription:"סטופ נגרר תוך-יומי בחברות מימון: הסטופ עולה בזמן אמת, גם לפי רווח פתוח. דוגמה במספרים, ההבדל מסטופ סוף יום, ואיך לנהל עסקאות כשיש לכם סטופ כזה.",lead:"בסטופ תוך-יומי, קו ההפסד עולה בזמן אמת לפי השיא של החשבון, כולל רווח פתוח בעסקה שעדיין לא סגרתם. עסקה שהגיעה לרווח וחזרה יכולה לשרוף את החשבון.",sections:[{title:"דוגמה",body:['חשבון של 50,000 עם סטופ של 2,000. נכנסתם לעסקה, והיא הגיעה לרווח של 1,000 דולר. לא סגרתם. ברגע הזה הסטופ כבר עלה ל-49,000. אם העסקה חוזרת וממשיכה להפסיד עד 49,000, החשבון נשרף, למרות שבפועל אף פעם לא "הרווחתם" את ה-1,000.']},{title:"איך עובדים עם סטופ כזה",body:["• יעד ברור לכל עסקה, וסגירה כשהוא מגיע. לא נותנים לרווח גדול לחזור לאפס.","• קידום סטופ לנקודת הכניסה כשהעסקה מתקדמת.",'• אם אתם סוחרים שאוהבים לתת לעסקה "לנשום", כדאי לבחור מסלול עם סטופ סוף יום.']}],image:{src:"/blog/tik-nostro/l3-trailing-intraday-vs-eod.jpg",alt:"טריילינג תוך-יומי מול טריילינג סוף יום"},faq:[{q:"רווח פתוח מזיז את הסטופ?",a:"כן. זה ההבדל המרכזי מסטופ סוף יום: הסטופ עולה לפי השיא של שווי החשבון בזמן אמת, גם לפני שסגרתם את העסקה."},{q:"הסטופ התוך-יומי ננעל מתישהו?",a:"ברוב החשבונות הממומנים כן, בנקודה מסוימת (בדרך כלל סביב גובה החשבון ההתחלתי). "+e}],articles:["tik-nostro"]},{id:"eod-trailing-drawdown",seoTitle:"סטופ סוף יום (EOD Trailing Drawdown): מה זה ולמה הוא מתאים למתחילים",seoDescription:"סטופ סוף יום (EOD) בחברות מימון: הסטופ מתעדכן רק לפי היתרה בסגירת היום. דוגמה במספרים, יתרונות מול סטופ תוך-יומי, ואיך לנצל את המרחב שהוא נותן.",lead:"בסטופ סוף יום (EOD), קו ההפסד מתעדכן רק לפי היתרה שבה סגרתם את יום המסחר. מה שקרה באמצע היום, רווח או הפסד זמני, לא מזיז אותו.",sections:[{title:"דוגמה",body:["חשבון של 50,000 עם סטופ של 2,000. במהלך היום הגעתם ל-52,000, אבל סגרתם את היום ב-51,000. הסטופ לא עלה ל-50,000, אלא ל-49,000: 2,000 פחות מהיתרה של סוף היום. מחר בבוקר מתחילים עם סטופ של 49,000."]},{title:"למה הוא נוח יותר",body:["• אפשר לתת לעסקה טובה לנשום בלי שהסטופ ירדוף אחריכם באמצע היום.","• בתוך היום, כל עוד לא הגעתם לסטופ של הבוקר, יש לכם את כל המרווח. לכן יש סוחרים שמנצלים את היום הראשון כדי להגיע לרווח משמעותי, ומקדמים סטופ לכניסה כדי לא לאבד אותו.","• בשביל זה אני ממליץ למתחילים לבחור במבחן מסלול עם סטופ סוף יום."]}],image:{src:"/blog/tik-nostro/l3-trailing-intraday-vs-eod.jpg",alt:"טריילינג סוף יום מול טריילינג תוך-יומי"},faq:[{q:'באיזו שעה נחשב "סוף היום"?',a:"לפי סגירת יום המסחר של החברה, בדרך כלל בשעות אחר הצהריים של ניו יורק. את השעה המדויקת בודקים בחוקי החברה."},{q:"גם בסטופ סוף יום אפשר להישרף באמצע היום?",a:"כן, אם יורדים מתחת לסטופ שנקבע בסוף היום הקודם. מה שלא קורה הוא שהסטופ יעלה באמצע היום."}],articles:["tik-nostro","how-to-pass-prop-firm-evaluation"]},{id:"static-drawdown",seoTitle:"דראודאון קבוע (Static Drawdown): הסטופ שלא זז",seoDescription:"מה זה Static Drawdown בחברות מימון: סטופ שנשאר במקום ולא עולה עם הרווחים. ההבדל מטריילינג דראודאון, יתרונות, חסרונות ולמי זה מתאים.",lead:"דראודאון קבוע הוא סטופ שנקבע פעם אחת ולא זז, גם כשאתם מרוויחים. כל רווח שאתם צוברים מרחיק אתכם ממנו.",sections:[{title:"דוגמה",body:["חשבון של 50,000 עם סטופ קבוע של 2,000: הסטופ על 48,000. הרווחתם 3,000 והחשבון על 53,000? הסטופ עדיין על 48,000, כלומר יש לכם עכשיו מרווח של 5,000 דולר."]},{title:"מתי זה טוב יותר",body:["• אחרי שצברתם רווח, יש הרבה יותר מרחב מאשר בסטופ נגרר.","• קל להבין ולחשב: הקו תמיד באותו מקום.","• החיסרון: בדרך כלל המבחנים עם סטופ קבוע יקרים יותר, או שהסטופ עצמו קטן יותר. "+e]}],faq:[{q:"מה ההבדל בין סטופ קבוע לנגרר?",a:"סטופ קבוע נשאר באותו מקום כל הזמן. סטופ נגרר עולה יחד עם השיא של החשבון, ולכן מקטין את המרווח כשאתם ברווח."}],articles:["tik-nostro"]},{id:"daily-loss-limit",seoTitle:"הגבלת הפסד יומית (Daily Loss Limit) בחברות מימון: מה זה ואיך לא להיפסל",seoDescription:"מה זה Daily Loss Limit (DLL) בחברות מימון: ההפסד המקסימלי המותר ביום אחד, מה קורה כשמגיעים אליו, ואיך להגדיר לעצמכם סטופ יומי שעוצר לפני כן.",lead:"הגבלת הפסד יומית (DLL) היא ההפסד המקסימלי שמותר ביום מסחר אחד. כשמגיעים אליה, בחלק מהחברות המסחר נחסם עד מחר, ובחלק החשבון נפסל.",sections:[{title:"שני סוגים של תוצאה",body:["• חסימה ליום: המסחר נעצר, וממשיכים מחר. החשבון חי.","• פסילה: החשבון נשרף, כמו בסטופ הכללי. "+e]},{title:"הסטופ היומי שלכם צריך להיות קטן יותר",body:['אני ממליץ לקבוע לעצמכם סטופ יומי קטן מההגבלה של החברה, ולהגדיר אותו במערכת. המטרה היא לא להגיע אליו, הוא רק רשת ביטחון למקרים שבהם השוק קופץ פתאום. אחרי יום הפסד, עוצרים ולא מנסים "להחזיר".']}],faq:[{q:"יש חברות בלי הגבלת הפסד יומית?",a:"כן, יש מסלולים בלי DLL, ויש מסלולים שבהם ההגבלה רק עוצרת את היום. אפשר לסנן לפי זה בהשוואת החברות."}],articles:["trading-plan","trading-psychology"]},{id:"buffer",seoTitle:"באפר (Buffer) בחברות מימון: מה זה כרית הביטחון לפני משיכה",seoDescription:"מה זה באפר או כרית ביטחון בחשבון ממומן: למה צריך לצבור אותו לפני משיכה, דוגמה בחשבון 50,000, ומה קורה לבאפר כשסוגרים חשבון.",lead:"באפר הוא כרית ביטחון: סכום שצריך לצבור מעל גובה החשבון לפני שמותר למשוך רווחים, ובחלק מהחברות גם להשאיר בחשבון אחרי המשיכה.",sections:[{title:"דוגמה",body:["חשבון של 50,000 עם באפר של 2,000. צריך להגיע ל-52,000, ורק מה שמעל זה אפשר למשוך. הגעתם ל-52,500? אפשר למשוך 500. הגעתם ל-53,000? אפשר למשוך 1,000."]},{title:"למה החברות דורשות באפר",body:["אם הייתם מושכים הכול, החשבון היה נשאר צמוד לסטופ, ועסקה רעה אחת הייתה שורפת אותו. הבאפר שומר מרחק בין היתרה לסטופ. "+e]}],image:{src:"/blog/tik-nostro/l2-after-passing.jpg",alt:"מה קורה אחרי שעוברים את המבחן: מבחן, חשבון ממומן, חשבון לייב"},faq:[{q:"אפשר למשוך גם מתוך הבאפר?",a:"בדרך כלל לא במשיכה רגילה. בחלק מהחברות אפשר למשוך חלק מהבאפר כשסוגרים את החשבון. במאמר על הבאפר בטייק פרופיט יש דוגמה מלאה."}],articles:["takeprofit-buffer-withdrawal","tik-nostro"]},{id:"activation-fee",seoTitle:"דמי הפעלה (Activation Fee) בחברות מימון: מה זה ומתי משלמים",seoDescription:"מה זה דמי הפעלה בחברות מימון ונוסטרו: תשלום אחרי מעבר המבחן ולפני החשבון הממומן. איך לחשב את העלות האמיתית של מבחן, ואיך מוצאים מסלולים בלי דמי הפעלה.",lead:"דמי הפעלה הם תשלום שחלק מחברות המימון גובות אחרי שעברתם את המבחן, לפני שמקבלים את החשבון הממומן. זה חלק מהעלות האמיתית של המבחן.",sections:[{title:"למה זה חשוב בהשוואה",body:["מבחן זול עם דמי הפעלה גבוהים יכול לעלות בסוף יותר ממבחן יקר בלי דמי הפעלה. לכן משווים את העלות הכוללת: מחיר המבחן (כולל חידושים חודשיים, אם יש) ועוד דמי ההפעלה.","יש גם הנחות שחלות רק על המבחן ולא על דמי ההפעלה. "+e]}],faq:[{q:"משלמים דמי הפעלה גם אם לא עוברים?",a:"לא. משלמים אותם רק אחרי שעוברים את המבחן, כדי להפעיל את החשבון הממומן."},{q:"יש חברות בלי דמי הפעלה?",a:"כן. בהשוואת החברות אפשר לראות לכל מסלול אם יש דמי הפעלה ומה גובהם."}],articles:["tik-nostro"]},{id:"funded-account",seoTitle:"חשבון ממומן (Funded Account): דמו או כסף אמיתי?",seoDescription:"מה זה חשבון ממומן בחברות מימון: למה הוא בדרך כלל עדיין דמו, איך משלמים לכם משיכות מכסף אמיתי, ומתי סוחרים עוברים לחשבון לייב שמחובר לבורסה.",lead:"חשבון ממומן הוא החשבון שמקבלים אחרי שעוברים מבחן. ממנו כבר אפשר למשוך רווחים, אבל ברוב החברות הוא עדיין חשבון דמו ולא מחובר לבורסה.",sections:[{title:"למה הוא עדיין דמו",body:["החברות יודעות שרוב מי שעובר מבחן ישרוף גם את החשבון הממומן. כדי לא להפסיד כסף אמיתי, החשבון נשאר דמו. כשמגיעים ליעד משיכה, החברה משלמת לכם מהכיס שלה, בכסף אמיתי לכל דבר."]},{title:"ומה זה חשבון לייב",body:["סוחר שמוכיח את עצמו לאורך זמן, עם משיכות ועקביות, מועבר לפי שיקול דעת החברה לחשבון לייב שמחובר לבורסה. זה לא תמיד שדרוג: בחשבון לייב החוקים לרוב קשוחים יותר, ויש סוחרים שמעדיפים להישאר בממומן ולמשוך ממנו."]}],image:{src:"/blog/tik-nostro/l2-after-passing.jpg",alt:"מבחן, חשבון ממומן (עדיין דמו) וחשבון לייב"},faq:[{q:"הכסף שמושכים מחשבון ממומן אמיתי?",a:"כן. גם אם החשבון הוא דמו, המשיכה משולמת בכסף אמיתי."},{q:"כמה זמן לוקח לקבל חשבון ממומן?",a:"מיד אחרי שעוברים את המבחן, ולפעמים אחרי תשלום דמי הפעלה."}],articles:["tik-nostro"]},{id:"minimum-trading-days",seoTitle:"ימי מסחר מינימליים בחברות מימון: מה זה ואיך זה עובד",seoDescription:"מה זה ימי מסחר מינימליים במבחן ובחשבון ממומן: למה החברות דורשות אותם, מה נחשב יום מסחר, ואיך לתכנן את המבחן כדי לא לבזבז ימים.",lead:"ימי מסחר מינימליים הם מספר הימים שחייבים לסחור בהם לפני שעוברים מבחן או מבקשים משיכה, גם אם כבר הגעתם ליעד.",sections:[{title:"למה זה קיים",body:["החברות רוצות לראות שהגעתם ליעד לאורך כמה ימים, ולא בעסקה אחת. בדרך כלל זה משתלב עם חוק העקביות."]},{title:"איך מתכננים",body:['• הגעתם ליעד לפני מספר הימים? אפשר להשלים את הימים החסרים בעסקאות קטנות. בחלק מהחברות יש הגדרה מה נחשב "יום מסחר", ולכן בודקים את החוק.',"• עדיף להרוויח את רוב היעד בימים הראשונים, ולא לבזבז ימים בהתחלה. אם משהו משתבש, לפחות לא איבדתם זמן. "+e]}],faq:[{q:"יום מסחר הוא כל יום שפתחתי בו עסקה?",a:"לרוב כן, אבל בחלק מהחברות יש דרישה מינימלית ליום מסחר (למשל רווח מינימלי או עסקה אחת לפחות). בודקים בחוקי החברה."}],articles:["how-to-pass-prop-firm-evaluation"]},{id:"profit-split",seoTitle:"פרופיט ספליט (Profit Split): כמה מהרווח נשאר אצלכם",seoDescription:"מה זה Profit Split בחברות מימון: איך מתחלקים הרווחים בין הסוחר לחברה, למה האחוז משתנה בין שלבים ומסלולים, ואיך להשוות בין חברות.",lead:"פרופיט ספליט הוא החלוקה של הרווחים בין הסוחר לחברת המימון. למשל, בחלוקה של 90/10, 90% מהרווח שאתם מושכים הולך אליכם ו-10% לחברה.",sections:[{title:"מה חשוב לדעת",body:["• בחלק מהחברות האחוז עולה אחרי כמה משיכות, או אחרי סכום מסוים. לפעמים המשיכה הראשונה מלאה ואחר כך יש חלוקה.","• אחוז גבוה לא מספיק. חשוב גם מתי מותר למשוך, כמה מקסימום בכל משיכה, ואם יש באפר.","• "+e]}],faq:[{q:"מה עדיף, חלוקה גבוהה או משיכות תכופות?",a:"תלוי בסגנון שלכם. לסוחר שמרוויח סכומים קבועים, משיכות תכופות שוות לפעמים יותר מכמה אחוזים בחלוקה."}],articles:["tik-nostro"]},{id:"scaling-plan",seoTitle:"תוכנית סקיילינג (Scaling Plan) בחברות מימון: מה זה ואיך זה עובד",seoDescription:"מה זה סקיילינג בחברות מימון: מגבלה על מספר החוזים שעולה בהדרגה ככל שהחשבון גדל. דוגמה במספרים, ולמה כדאי לגדול לאט גם כשאין חוק כזה.",lead:"תוכנית סקיילינג מגבילה את מספר החוזים שמותר לסחור בהם, ומגדילה אותו בהדרגה ככל שהחשבון ברווח. כמו מדרגות.",sections:[{title:"דוגמה",body:["בחשבון שמותר בו עד 5 חוזים, חוק סקיילינג יכול להיראות כך: בין 50,000 ל-51,000 מותר חוזה אחד, בין 51,000 ל-52,000 שני חוזים, ומעל 52,000 שלושה. ככה החברה לא נותנת לכם את כל הכוח ביום הראשון."]},{title:"הטיפ שלי",body:["גם כשאין חוק סקיילינג, כדאי לגדול לאט: חשבון אחד, משיכה ראשונה, ורק אז עוד חשבון או עוד חוזה. "+e]}],video:{id:"8TDjNdsZCoI",title:"מה זה סקיילינג?"},image:{src:"/blog/tik-nostro/l3-news-and-scaling.jpg",alt:"מסחר בחדשות ומגבלת סקיילינג"},faq:[{q:"מה קורה אם נכנסתי עם יותר חוזים מהמותר?",a:"תלוי בחברה: לפעמים העסקה פשוט נחסמת, ולפעמים זו הפרת חוק שעלולה לפסול את החשבון. כדאי להגדיר מראש בפלטפורמה כמות מקסימלית."}],articles:["tik-nostro"]},{id:"news-trading",seoTitle:"מסחר בחדשות בחברות מימון: מה מותר, מה אסור ולמה זה מסוכן",seoDescription:"מסחר בזמן הודעות כלכליות בחברות מימון: אילו הודעות, אילו מגבלות יש (דקות לפני ואחרי), ההבדל בין מבחן לחשבון ממומן, ולמה גם כשמותר כדאי להיזהר.",lead:"חלק מחברות המימון אוסרות להחזיק עסקה פתוחה סביב הודעות כלכליות חשובות, כמו ריבית, אינפלציה ונתוני תעסוקה. בדרך כלל ההגבלה היא כמה דקות לפני ההודעה ואחריה.",sections:[{title:"מה חשוב לדעת",body:["• בהרבה חברות מותר במבחן ואסור בחשבון הממומן.","• ההודעות שבדרך כלל נכללות: ריבית (FOMC), אינפלציה (CPI) ותעסוקה (NFP).","• את מועדי ההודעות של השבוע רואים ביומן הכלכלי באתר. "+e]},{title:"גם כשמותר",body:["בהודעה המחיר יכול לקפוץ ולחזור בשניות, והמערכת לא תמיד מצליחה לבצע את הסטופ במחיר שקבעתם. יש סוחרים מתקדמים שמשתמשים בזה כדי לעבור מבחנים גדולים, אבל זה הימור, ולא דרך לעבוד בחשבון ממומן."]}],video:{id:"ieUpkGK-tJA",title:"מה זה מסחר בזמן חדשות?"},faq:[{q:"כמה זמן לפני הודעה צריך לסגור עסקאות?",a:"תלוי בחברה, בדרך כלל כמה דקות לפני ואחרי. בודקים בלשונית החוקים בעמוד החברה."}],articles:["how-to-pass-prop-firm-evaluation"]},{id:"hedging",seoTitle:"גידור (Hedging) בחברות מימון: מה אסור ולמה",seoDescription:"מה זה גידור בחברות מימון ונוסטרו: החזקת פוזיציות מנוגדות, לונג ושורט בשני חשבונות, ולמה זה אסור ברוב החברות ועלול לעלות לכם במשיכה.",lead:"גידור הוא החזקה של פוזיציות מנוגדות כדי לצמצם סיכון. בחברות מימון רוב החברות אוסרות את זה, בעיקר לונג בחשבון אחד ושורט בחשבון אחר.",sections:[{title:"למה זה אסור",body:['כשפותחים לונג בחשבון אחד ושורט בשני, אחד מהם כמעט תמיד "יעבור". זו לא מיומנות מסחר, אלא ניצול של המודל. החברות מזהות את זה, ועלולות לסרב לשלם משיכה או לחסום את החשבונות.',"לא עושים את זה. גם כשזה נראה כמו דרך קלה לעבור מבחנים, זה פוגע באמון של החברה בכם."]}],video:{id:"t5zcg-0s19I",title:"מה זה גידור (Hedging)?"},faq:[{q:"מותר לסחור בכמה חשבונות באותו כיוון?",a:"בדרך כלל כן, עם תוכנת העתקת עסקאות (Copy Trade). מה שאסור הוא כיוונים מנוגדים."}],articles:["how-to-pass-prop-firm-evaluation"]},{id:"micro-scalping",seoTitle:"מיקרו סקאלפינג בחברות מימון: מה נחשב ולמה זה מוגבל",seoDescription:"מה זה מיקרו סקאלפינג: עסקאות של שניות בודדות על תנועות קטנות מאוד. למה חלק מחברות המימון מגבילות את זה, ואיך לבדוק את החוק בכל חברה.",lead:"מיקרו סקאלפינג הוא סגנון של עסקאות קצרות מאוד, לפעמים שניות, על תנועות מחיר קטנות. חלק מחברות המימון מגבילות אותו, בעיקר כשרוב הרווח מגיע מעסקאות כאלה.",sections:[{title:"למה זה מוגבל",body:["בחשבון דמו, עסקאות של שניות מנצלות לפעמים מחירים שלא היו מתמלאים בשוק האמיתי. לכן חלק מהחברות קובעות זמן החזקה מינימלי, או בודקות איזה חלק מהרווח הגיע מעסקאות קצרות מאוד. "+e]}],video:{id:"vLjRp9Ig9qw",title:"מה זה מיקרו סקאלפינג?"},faq:[{q:"סקאלפינג רגיל מותר?",a:"ברוב החברות כן. ההגבלה היא על עסקאות קצרות מאוד, ובדרך כלל רק כשהן מקור עיקרי לרווח."}],articles:["tik-nostro"]}],a=i=>t.find(n=>n.id===i),r=new Set(t.map(i=>i.id));export{o as G,r as T,a as f};
